MILES_TO_KM = 1.609344
POUNDS_TO_KG = 0.45359237
GALLONS_TO_LITERS = 3.785411784


def celsius_to_fahrenheit(value):
    return value * 9.0 / 5.0 + 32.0


def fahrenheit_to_celsius(value):
    return (value - 32.0) * 5.0 / 9.0


def miles_to_kilometers(value):
    return value * MILES_TO_KM


def kilometers_to_miles(value):
    return value / MILES_TO_KM


def pounds_to_kilograms(value):
    return value * POUNDS_TO_KG


def kilograms_to_pounds(value):
    return value / POUNDS_TO_KG


def gallons_to_liters(value):
    return value * GALLONS_TO_LITERS


def liters_to_gallons(value):
    return value / GALLONS_TO_LITERS


CONVERSIONS = {
    ('celsius', 'fahrenheit'): celsius_to_fahrenheit,
    ('fahrenheit', 'celsius'): fahrenheit_to_celsius,
    ('miles', 'kilometers'): miles_to_kilometers,
    ('kilometers', 'miles'): kilometers_to_miles,
    ('pounds', 'kilograms'): pounds_to_kilograms,
    ('kilograms', 'pounds'): kilograms_to_pounds,
    ('gallons', 'liters'): gallons_to_liters,
    ('liters', 'gallons'): liters_to_gallons,
}

ALIASES = {
    'c': 'celsius', 'f': 'fahrenheit',
    'mi': 'miles', 'km': 'kilometers',
    'lb': 'pounds', 'lbs': 'pounds', 'kg': 'kilograms',
    'gal': 'gallons', 'l': 'liters',
}


def normalize_unit(unit):
    name = str(unit).strip().lower()
    return ALIASES.get(name, name)


def lookup_conversion(source, target):
    key = (normalize_unit(source), normalize_unit(target))
    if key not in CONVERSIONS:
        raise ValueError('unsupported conversion: %s to %s' % key)
    return CONVERSIONS[key]


def convert(requests):
    results = []
    for value, source, target in requests:
        function = lookup_conversion(source, target)
        results.append(round(function(float(value)), 2))
    return results


def format_report(requests, results):
    lines = []
    for (value, source, target), result in zip(requests, results):
        lines.append('%g %s = %.2f %s' % (value, normalize_unit(source),
                                          result, normalize_unit(target)))
    return '\n'.join(lines)


def main():
    requests = [
        (100, 'celsius', 'fahrenheit'),
        (98.6, 'F', 'C'),
        (26.2, 'miles', 'km'),
        (5, 'kilometers', 'miles'),
        (150, 'lbs', 'kilograms'),
        (70, 'kg', 'pounds'),
        (2, 'gallons', 'liters'),
        (10, 'l', 'gal'),
    ]
    print(format_report(requests, convert(requests)))


if __name__ == '__main__':
    main()

