def validate_grid(grid):
    if not isinstance(grid, list) or not grid:
        raise ValueError("grid must be a non-empty list of rows")
    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("all rows must have the same length")
    return len(grid), width


def flip_horizontal(grid):
    return [list(reversed(row)) for row in grid]


def flip_vertical(grid):
    return [list(row) for row in reversed(grid)]


def transpose(grid):
    return [list(column) for column in zip(*grid)]


def rotate_clockwise(grid):
    return transpose(flip_vertical(grid))


def rotate_counterclockwise(grid):
    return flip_vertical(transpose(grid))


def invert(grid):
    return [[not value for value in row] for row in grid]


def main_diagonal(grid):
    height, width = validate_grid(grid)
    return [[grid[i][i] for i in range(min(height, width))]]


def anti_diagonal(grid):
    height, width = validate_grid(grid)
    return [[grid[i][width - 1 - i] for i in range(min(height, width))]]


TRANSFORMATIONS = {
    "flip_horizontal": flip_horizontal,
    "flip_vertical": flip_vertical,
    "rotate_clockwise": rotate_clockwise,
    "rotate_counterclockwise": rotate_counterclockwise,
    "transpose": transpose,
    "invert": invert,
    "main_diagonal": main_diagonal,
    "anti_diagonal": anti_diagonal,
}


def transform(grid, transformations):
    validate_grid(grid)
    result = [list(row) for row in grid]
    for name in transformations:
        if name not in TRANSFORMATIONS:
            raise KeyError("unknown transformation: %s" % name)
        result = TRANSFORMATIONS[name](result)
    return result


def format_grid(grid):
    return "\n".join("".join("#" if value else "." for value in row) for row in grid)


def main():
    grid = [
        [True, False, False],
        [True, True, False],
        [False, True, True],
    ]
    print(format_grid(grid))
    for steps in (["rotate_clockwise"], ["invert", "flip_horizontal"],
                  ["transpose", "main_diagonal"], ["anti_diagonal"]):
        print("\n" + " -> ".join(steps))
        print(format_grid(transform(grid, steps)))


if __name__ == "__main__":
    main()

