MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def day_of_year(year, month, day):
    total = day
    for m in range(1, month):
        total += days_in_month(year, m)
    return total


def remaining_days(year, month, day):
    total = 366 if is_leap_year(year) else 365
    return total - day_of_year(year, month, day)


def add_days(year, month, day, count):
    while count > 0:
        span = days_in_month(year, month)
        if day + count <= span:
            return (year, month, day + count)
        count -= span - day + 1
        day = 1
        month += 1
        if month > 12:
            month = 1
            year += 1
    return (year, month, day)


def subtract_days(year, month, day, count):
    while count > 0:
        if count < day:
            return (year, month, day - count)
        count -= day
        month -= 1
        if month < 1:
            month = 12
            year -= 1
        day = days_in_month(year, month)
    return (year, month, day)


def date_difference(first, second):
    def absolute(date):
        y, m, d = date
        total = day_of_year(y, m, d)
        for year in range(1, y):
            total += 366 if is_leap_year(year) else 365
        return total
    return abs(absolute(second) - absolute(first))


def format_date(year, month, day):
    return "%s %d, %d" % (MONTH_NAMES[month - 1], day, year)


def shift_date(date, offset):
    year, month, day = date
    if offset < 0:
        return subtract_days(year, month, day, -offset)
    return add_days(year, month, day, offset)


def schedule(events):
    results = []
    for name, date, offset in events:
        new_date = shift_date(date, offset)
        gap = date_difference(date, new_date)
        left = remaining_days(*new_date)
        results.append(
            "%s: %s (%d days shifted, %d days left in year)"
            % (name, format_date(*new_date), gap, left)
        )
    return results


def main():
    events = [
        ("Kickoff", (2024, 2, 27), 5),
        ("Review", (2024, 12, 30), 10),
        ("Retro", (2023, 3, 1), -1),
        ("Launch", (2025, 1, 15), 400),
    ]
    for line in schedule(events):
        print(line)


if __name__ == "__main__":
    main()

