def validate(matrix):
    if len(matrix) != 2 or any(len(row) != 2 for row in matrix):
        raise ValueError("expected a 2x2 matrix, got %r" % (matrix,))
    return [[float(value) for value in row] for row in matrix]


def add(a, b):
    return [[a[i][j] + b[i][j] for j in range(2)] for i in range(2)]


def subtract(a, b):
    return [[a[i][j] - b[i][j] for j in range(2)] for i in range(2)]


def scalar_multiply(a, factor):
    return [[a[i][j] * factor for j in range(2)] for i in range(2)]


def matrix_multiply(a, b):
    return [[sum(a[i][k] * b[k][j] for k in range(2)) for j in range(2)]
            for i in range(2)]


def transpose(a):
    return [[a[j][i] for j in range(2)] for i in range(2)]


def trace(a):
    return a[0][0] + a[1][1]


def determinant(a):
    return a[0][0] * a[1][1] - a[0][1] * a[1][0]


def inverse(a):
    det = determinant(a)
    if det == 0:
        raise ValueError("matrix is singular and has no inverse")
    adjugate = [[a[1][1], -a[0][1]], [-a[1][0], a[0][0]]]
    return scalar_multiply(adjugate, 1.0 / det)


def compute(matrices, operation):
    first = validate(matrices[0])
    if operation == "scalar_multiply":
        return scalar_multiply(first, float(matrices[1]))
    if operation in ("transpose", "trace", "determinant", "inverse"):
        unary = {"transpose": transpose, "trace": trace,
                 "determinant": determinant, "inverse": inverse}
        return unary[operation](first)
    binary = {"add": add, "subtract": subtract, "multiply": matrix_multiply}
    if operation not in binary:
        raise ValueError("unknown operation: %s" % operation)
    return binary[operation](first, validate(matrices[1]))


