import html


def escape_text(text):
    return html.escape(str(text), quote=True)


def heading(text, level=1):
    if not 1 <= level <= 6:
        raise ValueError("heading level must be between 1 and 6")
    return "<h{0}>{1}</h{0}>".format(level, escape_text(text))


def paragraph(text):
    return "<p>{0}</p>".format(escape_text(text))


def bold(text):
    return "<strong>{0}</strong>".format(escape_text(text))


def italic(text):
    return "<em>{0}</em>".format(escape_text(text))


def hyperlink(text, href):
    return '<a href="{0}">{1}</a>'.format(escape_text(href), escape_text(text))


def image(src, alt=""):
    return '<img src="{0}" alt="{1}">'.format(escape_text(src), escape_text(alt))


def list_item(text):
    return "<li>{0}</li>".format(escape_text(text))


def unordered_list(items):
    return "<ul>{0}</ul>".format("".join(list_item(item) for item in items))


def render_element(kind, content):
    if kind == "heading":
        if isinstance(content, (list, tuple)):
            return heading(content[0], content[1])
        return heading(content)
    if kind == "paragraph":
        return paragraph(content)
    if kind == "bold":
        return bold(content)
    if kind == "italic":
        return italic(content)
    if kind == "link":
        return hyperlink(content[0], content[1])
    if kind == "image":
        return image(content[0], content[1] if len(content) > 1 else "")
    if kind == "list":
        return unordered_list(content)
    if kind == "item":
        return list_item(content)
    raise ValueError("unknown element type: {0!r}".format(kind))


def render(elements):
    return "".join(render_element(kind, content) for kind, content in elements)


