OPERATION_NAMES = (
    'normalize',
    'trim',
    'dirname',
    'filename',
    'extension',
    'absolute',
    'parent',
    'join',
)


def normalize_slashes(path):
    unified = path.replace('\\', '/')
    while '//' in unified:
        unified = unified.replace('//', '/')
    return unified


def remove_trailing_slashes(path):
    cleaned = normalize_slashes(path)
    while len(cleaned) > 1 and cleaned.endswith('/'):
        cleaned = cleaned[:-1]
    return cleaned


def directory_name(path):
    cleaned = remove_trailing_slashes(path)
    if '/' not in cleaned:
        return '.'
    head = cleaned.rsplit('/', 1)[0]
    return head or '/'


def file_name(path):
    cleaned = remove_trailing_slashes(path)
    return cleaned.rsplit('/', 1)[-1]


def file_extension(path):
    name = file_name(path)
    dot = name.rfind('.')
    if dot <= 0:
        return ''
    return name[dot + 1:]


def is_absolute(path):
    cleaned = normalize_slashes(path)
    if cleaned.startswith('/'):
        return True
    return len(cleaned) > 1 and cleaned[1] == ':'


def join_paths(left, right):
    if is_absolute(right):
        return remove_trailing_slashes(right)
    head = remove_trailing_slashes(left)
    tail = normalize_slashes(right).lstrip('/')
    if head in ('', '.'):
        return remove_trailing_slashes(tail)
    if head.endswith('/'):
        return remove_trailing_slashes(head + tail)
    return remove_trailing_slashes(head + '/' + tail)


def parent_directory(path):
    cleaned = remove_trailing_slashes(path)
    if cleaned in ('/', '.', ''):
        return cleaned or '.'
    return directory_name(cleaned)


def parse_operation(operation):
    name, _, argument = operation.partition(':')
    name = name.strip().lower()
    if name not in OPERATION_NAMES:
        raise ValueError('unknown operation: ' + name)
    if name == 'join' and not argument:
        raise ValueError('join requires a second segment, e.g. "join:sub/dir"')
    return name, argument


def process(paths, operation):
    name, argument = parse_operation(operation)
    handlers = {
        'normalize': normalize_slashes,
        'trim': remove_trailing_slashes,
        'dirname': directory_name,
        'filename': file_name,
        'extension': file_extension,
        'absolute': lambda path: str(is_absolute(path)),
        'parent': parent_directory,
        'join': lambda path: join_paths(path, argument),
    }
    handler = handlers[name]
    return [handler(path) for path in paths]


def main():
    paths = [
        '/usr//local/bin/tool.tar.gz',
        'C:\\Users\\dev\\notes.txt',
        'docs/guide/',
        'README',
    ]
    for operation in OPERATION_NAMES[:-1] + ('join:extra/data.bin',):
        results = process(paths, operation)
        print('{:<10} {}'.format(operation, ' | '.join(results)))


if __name__ == '__main__':
    main()

