        return remove_trailing_slashes(head + tail)
    return remove_trailing_slashes(head + '/' + tail)

def parent_directory(path):
    cleaned = remove_trailing_slashes(path)
    if cleaned in ('/', '.', ''):
        return cleaned or '.'
    return directory_name(cleaned)

def parse_operation(operation):
    name, _, argument = operation.partition(':')
    name = name.strip().lower()
    if name not in OPERATION_NAMES:
        raise ValueError('unknown operation: ' + name)
    if name == 'join' and not argument:
        raise ValueError('join requires a second segment, e.g. "join:sub/dir"')
    return name, argument

