        'normalize': normalize_slashes,
        'trim': remove_trailing_slashes,
        'dirname': directory_name,
        'filename': file_name,
        'extension': file_extension,
        'absolute': lambda path: str(is_absolute(path)),
        'parent': parent_directory,
        'join': lambda path: join_paths(path, argument),
    }
    handler = handlers[name]
    return [handler(path) for path in paths]

