def trim(poly):
    coefficients = list(poly)
    while coefficients and coefficients[-1] == 0:
        coefficients.pop()
    return coefficients


def evaluate_at(poly, x):
    total = 0
    for coefficient in reversed(poly):
        total = total * x + coefficient
    return total


def add(p, q):
    length = max(len(p), len(q))
    return trim([
        (p[i] if i < len(p) else 0) + (q[i] if i < len(q) else 0)
        for i in range(length)
    ])


def subtract(p, q):
    length = max(len(p), len(q))
    return trim([
        (p[i] if i < len(p) else 0) - (q[i] if i < len(q) else 0)
        for i in range(length)
    ])


def scalar_multiply(poly, factor):
    return trim([coefficient * factor for coefficient in poly])


def multiply(p, q):
    if not trim(p) or not trim(q):
        return []
    product = [0] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            product[i + j] += a * b
    return trim(product)


def derivative(poly):
    return trim([power * poly[power] for power in range(1, len(poly))])


def integral(poly, constant=0):
    result = [constant]
    for power, coefficient in enumerate(poly):
        quotient = coefficient / (power + 1)
        result.append(int(quotient) if quotient == int(quotient) else quotient)
    return trim(result)


def degree(poly):
    return len(trim(poly)) - 1


OPERATIONS = {
    "eval": evaluate_at,
    "add": add,
    "sub": subtract,
    "scale": scalar_multiply,
    "mul": multiply,
    "deriv": derivative,
    "integ": integral,
    "degree": degree,
}


def evaluate(tasks):
    results = []
    for task in tasks:
        operation, arguments = task[0], task[1:]
        handler = OPERATIONS.get(operation)
        if handler is None:
            raise ValueError("unknown operation: %r" % (operation,))
        results.append(handler(*arguments))
    return results


def format_poly(poly):
    coefficients = trim(poly)
    if not coefficients:
        return "0"
    terms = []
    for power in range(len(coefficients) - 1, -1, -1):
        coefficient = coefficients[power]
        if coefficient == 0:
            continue
        if power == 0:
            terms.append(str(coefficient))
        elif power == 1:
            terms.append("%sx" % (coefficient,))
        else:
            terms.append("%sx^%d" % (coefficient, power))
    return " + ".join(terms)


def format_result(result):
    if isinstance(result, list):
        return format_poly(result)
    return str(result)


def main():
    tasks = [
        ("eval", [1, 0, 3], 2),
        ("add", [1, 2], [3, 4, 5]),
        ("sub", [1, 2, 5], [0, 2, 5]),
        ("scale", [1, -2, 3], 3),
        ("mul", [1, 1], [-1, 1]),
        ("deriv", [5, 4, 3, 2]),
        ("integ", [2, 6], 1),
        ("degree", [7, 0, 0, 4, 0]),
    ]
    for task, result in zip(tasks, evaluate(tasks)):
        print("%-7s %s -> %s" % (task[0], task[1:], format_result(result)))


if __name__ == "__main__":
    main()

