def validate_cart(cart):
    if not isinstance(cart, (list, tuple)):
        raise TypeError("cart must be a list of item prices")
    for price in cart:
        if not isinstance(price, (int, float)) or isinstance(price, bool):
            raise TypeError("item prices must be numbers")
        if price < 0:
            raise ValueError("item prices must not be negative")
    return list(cart)


def cart_total(cart):
