def shift_up(signal):
    return [sample + 10 for sample in signal]


def double_volume(signal):
    return [sample * 2 for sample in signal]


def halve_volume(signal):
    return [sample / 2 for sample in signal]


def hard_clip(signal):
    return [80 if sample > 80 else sample for sample in signal]


def soft_floor(signal):
    return [20 if sample < 20 else sample for sample in signal]


def add_white_noise(signal):
    return [sample + 5 for sample in signal]


def invert_phase(signal):
    return [-sample for sample in signal]


def rectify(signal):
    return [0 if sample < 0 else sample for sample in signal]


def validate(signal):
    if not isinstance(signal, (list, tuple)):
        raise TypeError("signal must be a list of numeric samples")
    for sample in signal:
        if isinstance(sample, bool) or not isinstance(sample, (int, float)):
            raise TypeError("sample %r is not numeric" % (sample,))
    return list(signal)


def modulate(signal):
    samples = validate(signal)
    effects = (
        shift_up,
        double_volume,
        halve_volume,
        hard_clip,
        soft_floor,
        add_white_noise,
        invert_phase,
        rectify,
    )
    return [effect(samples) for effect in effects]


def format_sample(sample):
    if isinstance(sample, float) and sample.is_integer():
        return str(int(sample))
    return str(sample)


def report(signal):
    names = [
        "shift up by ten",
        "double volume",
        "halve volume",
        "hard clip at eighty",
        "soft floor at twenty",
        "white noise plus five",
        "invert phase",
        "zero negatives",
    ]
    width = max(len(name) for name in names)
    lines = ["input: [%s]" % ", ".join(format_sample(s) for s in signal)]
    for name, result in zip(names, modulate(signal)):
        rendered = ", ".join(format_sample(s) for s in result)
        lines.append("%-*s -> [%s]" % (width, name, rendered))
    return "\n".join(lines)


def main():
    print(report([50, -30]))


if __name__ == "__main__":
    main()

