def validate_point(point):
    if len(point) != 2:
        raise ValueError("a point must contain exactly two coordinates")
    x, y = point
    for value in (x, y):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("coordinates must be numbers")
    return float(x), float(y)


def translate_x(point):
    x, y = point
    return (x + 5, y)


def translate_y(point):
    x, y = point
    return (x, y - 3)


def scale_up(point):
    x, y = point
    return (x * 2, y * 2)


def scale_down(point):
    x, y = point
    return (x / 2, y / 2)


def reflect_x_axis(point):
    x, y = point
    return (x, -y)


def reflect_y_axis(point):
    x, y = point
    return (-x, y)


def swap_coordinates(point):
    x, y = point
    return (y, x)


def project_to_x_axis(point):
    return (point[0], 0.0)


def transform(point):
    start = validate_point(point)
    operations = (
        translate_x,
        translate_y,
        scale_up,
        scale_down,
        reflect_x_axis,
        reflect_y_axis,
        swap_coordinates,
        project_to_x_axis,
    )
    return [operation(start) for operation in operations]


def format_point(point):
    x, y = point
    return "({0:g}, {1:g})".format(x, y)


def describe(point):
    lines = ["source: " + format_point(validate_point(point))]
    for result in transform(point):
        lines.append("  -> " + format_point(result))
    return "\n".join(lines)


def main():
    for sample in [(3, 4), (-1.5, 0), (10, -2)]:
        print(describe(sample))


if __name__ == "__main__":
    main()

