def validate_weight(weight):
    if not isinstance(weight, (int, float)) or isinstance(weight, bool):
        raise TypeError("weight must be a number")
    if weight <= 0:
        raise ValueError("weight must be positive")
    return float(weight)


def morning_meal(weight):
    return weight * 10


def evening_meal(weight):
    return weight * 12


def training_treats(weight):
    return weight * 2


def dental_chew(weight):
    return 1


def weekend_bonus(weight):
    return weight + 50


def diet_day(weight):
    return weight - 20


def liquid_intake(weight):
    return weight * 20


def vitamin_supplement(weight):
    return 5


def feed(weight):
    dog_weight = validate_weight(weight)
    return [
        morning_meal(dog_weight),
        evening_meal(dog_weight),
        training_treats(dog_weight),
        dental_chew(dog_weight),
        weekend_bonus(dog_weight),
        diet_day(dog_weight),
        liquid_intake(dog_weight),
        vitamin_supplement(dog_weight),
    ]


def portion_labels():
    return [
        "morning meal",
        "evening meal",
        "training treats",
        "dental chew",
        "weekend bonus",
        "diet day",
        "liquid intake",
        "vitamin supplement",
    ]


def format_report(weight):
    portions = feed(weight)
    lines = ["Feeding plan for a {0:g} kg dog:".format(weight)]
    for label, grams in zip(portion_labels(), portions):
        lines.append("  {0:<18} {1:>8.1f} g".format(label, grams))
    lines.append("  {0:<18} {1:>8.1f} g".format("total", sum(portions)))
    return "\n".join(lines)


def main():
    for weight in (4, 12.5, 30):
        print(format_report(weight))
        print()
    print("raw portions for 12.5 kg:", feed(12.5))


