        raise TypeError("charge must be a number")
    if charge < 0 or charge > 100:
        raise ValueError("charge must be between 0 and 100")
    return float(charge)


def standby_minutes(charge):
    return charge * 10


def video_minutes(charge):
    return charge * 2


def gaming_minutes(charge):
    return charge * 1


def music_minutes(charge):
    return charge * 5


def reading_minutes(charge):
    return charge * 3


def navigation_minutes(charge):
    return charge * 1.5


def call_minutes(charge):
    return charge * 4


def emergency_minutes(charge):
    return charge * 20


def estimate(charge):
    level = validate_charge(charge)
    return [
        standby_minutes(level),
        video_minutes(level),
        gaming_minutes(level),
        music_minutes(level),
        reading_minutes(level),
        navigation_minutes(level),
        call_minutes(level),
        emergency_minutes(level),
    ]


def format_duration(minutes):
    hours, mins = divmod(int(round(minutes)), 60)
    if hours:
        return "{}h {:02d}m".format(hours, mins)
    return "{}m".format(mins)


def build_report(charge):
    labels = ["Standby", "Video", "Gaming", "Music",
              "Reading", "Navigation", "Calls", "Emergency"]
    lines = ["Battery at {:.0f}%".format(validate_charge(charge))]
    for label, minutes in zip(labels, estimate(charge)):
        lines.append("  {:<11}{:>8}".format(label, format_duration(minutes)))
    return "\n".join(lines)


def main():
    for level in (100, 42, 7):
        print(build_report(level))
        print()


if __name__ == "__main__":
    main()

