def is_taller_than_ten(height):
    return height > 10


def is_shorter_than_five(height):
    return height < 5


def is_exactly_zero(height):
    return height == 0


def is_even_height(height):
    return height % 2 == 0


def is_multiple_of_three(height):
    return height % 3 == 0


def is_taller_than_fifty(height):
    return height > 50


def is_between_twenty_and_thirty(height):
    return 20 <= height <= 30


def is_shorter_than_one_hundred(height):
    return height < 100


INDICATORS = [
    ("taller than 10 cm", is_taller_than_ten),
    ("shorter than 5 cm", is_shorter_than_five),
    ("exactly 0 cm", is_exactly_zero),
    ("an even number of cm", is_even_height),
    ("a multiple of 3 cm", is_multiple_of_three),
    ("taller than 50 cm", is_taller_than_fifty),
    ("between 20 and 30 cm", is_between_twenty_and_thirty),
    ("shorter than 100 cm", is_shorter_than_one_hundred),
]


def validate_height(height):
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("plant height must be an integer number of centimeters")
    if height < 0:
        raise ValueError("plant height cannot be negative")
    return height


def project(height):
    validate_height(height)
    return [indicator(height) for _, indicator in INDICATORS]


def describe(height, results):
    lines = ["Plant height: %d cm" % height]
    for (label, _), result in zip(INDICATORS, results):
        lines.append("  %-24s %s" % (label + ":", "yes" if result else "no"))
    return "\n".join(lines)


def count_positive(results):
    return sum(1 for result in results if result)


def main():
    for height in (12, 0, 27, 64):
        results = project(height)
        print(describe(height, results))
        print("  matched indicators: %d of %d" % (count_positive(results), len(results)))
        print()


if __name__ == "__main__":
    main()

