def to_upper(text):
    return text.upper()


def capitalize_first(text):
    if not text:
        return text
    return text[0].upper() + text[1:]


def underscore_spaces(text):
    return text.replace(" ", "_")


def strip_spaces(text):
    return text.replace(" ", "")


def double_characters(text):
    return "".join(char * 2 for char in text)


def append_exclamation(text):
    return text + "!"


def prepend_question(text):
    return "?" + text


def repeat_twice(text):
    return text * 2


def format(text):
    styles = (
        to_upper,
        capitalize_first,
        underscore_spaces,
        strip_spaces,
        double_characters,
        append_exclamation,
        prepend_question,
        repeat_twice,
    )
    return [style(text) for style in styles]


def normalize_input(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return " ".join(text.lower().split())


def build_report(text):
    names = [
        "uppercase",
        "capitalized",
        "underscored",
        "no spaces",
        "doubled",
        "exclaimed",
        "questioned",
        "repeated",
    ]
    results = format(text)
    width = max(len(name) for name in names)
    return "\n".join(
        "{0:<{1}} : {2}".format(name, width, result)
        for name, result in zip(names, results)
    )


def main():
    sentence = normalize_input("  Hello   little   WORLD  ")
    print("input:", sentence)
    print(build_report(sentence))


if __name__ == "__main__":
    main()

