    return difficulty + 10


def artistic_bonus(difficulty):
    return difficulty * 1.5


def time_penalty(difficulty):
    return difficulty - 2


def perfect_landing_bonus(difficulty):
    return difficulty + 5


def stepping_penalty(difficulty):
    return difficulty - 1


def form_deduction(difficulty):
    return difficulty / 2


def combination_bonus(difficulty):
    return difficulty + 3


def crowd_appeal_bonus(difficulty):
    return difficulty + 4


def validate_difficulty(difficulty):
    if isinstance(difficulty, bool) or not isinstance(difficulty, int):
        raise TypeError("base difficulty must be an integer")
    if difficulty < 0:
        raise ValueError("base difficulty must not be negative")
    return difficulty


def score(difficulty):
    base = validate_difficulty(difficulty)
    return [
        base_execution(base),
        artistic_bonus(base),
        time_penalty(base),
        perfect_landing_bonus(base),
        stepping_penalty(base),
        form_deduction(base),
        combination_bonus(base),
        crowd_appeal_bonus(base),
    ]


