def minor_second(frequency):
    return frequency * 1.059


def major_second(frequency):
    return frequency * 1.122


def minor_third(frequency):
    return frequency * 1.189


def major_third(frequency):
    return frequency * 1.26


def perfect_fourth(frequency):
    return frequency * 1.33


def perfect_fifth(frequency):
    return frequency * 1.5


def major_sixth(frequency):
    return frequency * 1.68


def octave(frequency):
    return frequency * 2


def validate_frequency(frequency):
    if not isinstance(frequency, (int, float)):
        raise TypeError("frequency must be a number in hertz")
    if frequency <= 0:
        raise ValueError("frequency must be greater than zero")
    return float(frequency)


def harmonize(frequency):
    base = validate_frequency(frequency)
    builders = (
        minor_second,
        major_second,
        minor_third,
        major_third,
        perfect_fourth,
        perfect_fifth,
        major_sixth,
        octave,
    )
    return [builder(base) for builder in builders]


def interval_names():
    return [
        "minor second",
        "major second",
        "minor third",
        "major third",
        "perfect fourth",
        "perfect fifth",
        "major sixth",
        "octave",
    ]


def format_report(frequency):
    lines = ["Fundamental: {0:.2f} Hz".format(validate_frequency(frequency))]
    for name, pitch in zip(interval_names(), harmonize(frequency)):
        lines.append("  {0:<15} {1:8.2f} Hz".format(name, pitch))
    return "\n".join(lines)


def main():
    for fundamental in (440.0, 261.63):
        print(format_report(fundamental))


if __name__ == "__main__":
