    return 20


def gps_tracker_fee(days):
    return 5 * days


def young_driver_surcharge(days):
    return 10 * days


def booking_fee(days):
    return 15


def toll_pass_fee(days):
    return 8 * days


def final_discount(days):
    return -2 * days


def quote(days):
    validate_days(days)
    return [
        base_rate(days),
        insurance_fee(days),
        cleaning_fee(days),
        gps_tracker_fee(days),
        young_driver_surcharge(days),
        booking_fee(days),
        toll_pass_fee(days),
        final_discount(days),
    ]


def label_charges(charges):
    names = [
        "base rate",
        "insurance",
        "cleaning",
        "gps tracker",
        "young driver",
        "booking",
        "toll pass",
        "discount",
    ]
    return list(zip(names, charges))


def format_quote(days):
    charges = quote(days)
    lines = ["Quote for {} day(s):".format(days)]
    for name, amount in label_charges(charges):
        lines.append("  {:<13} {:>7.2f}".format(name, float(amount)))
    lines.append("  {:<13} {:>7.2f}".format("TOTAL", float(sum(charges))))
    return "\n".join(lines)


