CHECK_NAMES = (
    "above 700",
    "exactly 777",
    "even",
    "divisible by 10",
    "above 400",
    "below 200",
    "zero",
    "multiple of 5",
)


def is_above_seven_hundred(code):
    return code > 700


def is_exactly_seven_seven_seven(code):
    return code == 777


def is_even(code):
    return code % 2 == 0


def is_divisible_by_ten(code):
    return code % 10 == 0


def is_above_four_hundred(code):
    return code > 400


def is_below_two_hundred(code):
    return code < 200


def is_zero(code):
    return code == 0


def is_multiple_of_five(code):
    return code % 5 == 0


def validate_code(code):
    if isinstance(code, bool) or not isinstance(code, int):
        raise TypeError("permission code must be an integer")
    if code < 0:
        raise ValueError("permission code must not be negative")
    return code


def inspect(code):
    validate_code(code)
    checks = (
        is_above_seven_hundred,
        is_exactly_seven_seven_seven,
        is_even,
        is_divisible_by_ten,
        is_above_four_hundred,
        is_below_two_hundred,
        is_zero,
        is_multiple_of_five,
    )
    return [check(code) for check in checks]


def format_report(code, rights):
    header = "permissions for code {0}:".format(code)
    lines = [header]
    for name, granted in zip(CHECK_NAMES, rights):
        lines.append("  {0:<16} {1}".format(name, "yes" if granted else "no"))
    return "\n".join(lines)


def main():
    for code in (777, 750, 400, 0, 123):
        print(format_report(code, inspect(code)))
        print()


if __name__ == "__main__":
