def keep_positive(numbers):
    return [n for n in numbers if n > 0]


def keep_negative(numbers):
    return [n for n in numbers if n < 0]


def keep_even(numbers):
    return [n for n in numbers if n % 2 == 0]


def keep_odd(numbers):
    return [n for n in numbers if n % 2 != 0]


def keep_greater_than_ten(numbers):
    return [n for n in numbers if n > 10]


def keep_less_than_zero(numbers):
    return [n for n in numbers if n < 0]


def keep_divisible_by_three(numbers):
    return [n for n in numbers if n % 3 == 0]


def keep_divisible_by_five(numbers):
    return [n for n in numbers if n % 5 == 0]


def validate_group(group):
    if not isinstance(group, (list, tuple)):
        raise TypeError("group must be a list of integers")
    for value in group:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("group must contain integers only, got %r" % (value,))
    return list(group)


def filter(group):
    numbers = validate_group(group)
    return [
        keep_positive(numbers),
        keep_negative(numbers),
        keep_even(numbers),
        keep_odd(numbers),
        keep_greater_than_ten(numbers),
        keep_less_than_zero(numbers),
        keep_divisible_by_three(numbers),
        keep_divisible_by_five(numbers),
    ]


def format_report(results):
    labels = [
        "positive", "negative", "even", "odd",
        "greater than ten", "less than zero",
        "divisible by three", "divisible by five",
    ]
    width = max(len(label) for label in labels)
    lines = []
    for label, values in zip(labels, results):
        rendered = ", ".join(str(v) for v in values) if values else "(none)"
        lines.append("%s : %s" % (label.rjust(width), rendered))
    return "\n".join(lines)


def main():
    group = [-9, -4, -1, 0, 3, 5, 7, 10, 12, 15, 22, 33]
    results = filter(group)
    print("input : %s" % (group,))
    print(format_report(results))
    print("total kept values: %d" % sum(len(part) for part in results))


if __name__ == "__main__":
    main()

