def validate(series):
    if not isinstance(series, list):
        raise TypeError("series must be a list")
    if len(series) < 2:
        raise ValueError("series must contain at least two data points")
    if len(series) % 2 == 0:
        raise ValueError("series must have an odd number of data points")
    for value in series:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("series must contain only numbers")
    return series


def first_element(series):
    return series[0]


def last_element(series):
    return series[-1]


def span(series):
    return series[-1] - series[0]


def head_sum(series):
    return series[0] + series[1]


def tail_sum(series):
    return series[-2] + series[-1]


def first_magnitude(series):
    return abs(series[0])


def middle_element(series):
    return series[len(series) // 2]


def length(series):
    return len(series)


def process(series):
    validate(series)
    metrics = (first_element, last_element, span, head_sum, tail_sum,
               first_magnitude, middle_element, length)
    return [metric(series) for metric in metrics]


def format_report(series):
    labels = ["first", "last", "span", "head sum", "tail sum",
              "first magnitude", "middle", "length"]
    values = process(series)
    lines = ["series: {}".format(series)]
    for label, value in zip(labels, values):
        lines.append("  {:<16}{:g}".format(label, value))
    return "\n".join(lines)


def main():
    samples = [
        [-4, 2, 7, 9, 11],
        [3.5, 1.0, -2.5],
        [10, 20, 30, 40, 50, 60, 70],
    ]
    for sample in samples:
        print(format_report(sample))


if __name__ == "__main__":
    main()

