def is_uppercase_letter(value):
    return 65 <= value <= 90


def is_lowercase_letter(value):
    return 97 <= value <= 122


def is_digit_character(value):
    return 48 <= value <= 57


def is_space_character(value):
    return value == 32


def is_control_character(value):
    return value < 32


def is_beyond_ascii(value):
    return value > 127


def is_tab_character(value):
    return value == 9


def is_newline_character(value):
    return value == 10


def examine(value):
    return [
        is_uppercase_letter(value),
        is_lowercase_letter(value),
        is_digit_character(value),
        is_space_character(value),
        is_control_character(value),
        is_beyond_ascii(value),
        is_tab_character(value),
        is_newline_character(value),
    ]


def check_labels():
    return [
        "uppercase letter",
        "lowercase letter",
        "digit",
        "space",
        "control character",
        "beyond ascii",
        "tab",
        "newline",
    ]


def matching_labels(value):
    labels = check_labels()
    results = examine(value)
    return [label for label, flag in zip(labels, results) if flag]


def describe(value):
    matches = matching_labels(value)
    if not matches:
        return "U+{:04X}: no matching category".format(value)
    return "U+{:04X}: {}".format(value, ", ".join(matches))


def main():
    for code_point in (65, 90, 97, 122, 48, 57, 32, 9, 10, 0, 200, 8364):
        print(describe(code_point))
    print(examine(70))


if __name__ == "__main__":
    main()

