def express_air_fee(weight):
    return 5 * weight


def next_day_fee(weight):
    return express_air_fee(weight) + 20


def fragile_handling_fee(weight):
    return 10.0


def heavy_surcharge(weight):
    if weight > 50:
        return 15.0
    return 0.0


def rural_delivery_fee(weight):
    return 12.0


def international_base_fee(weight):
    return 50.0


def signature_required_fee(weight):
    return 3.0


def calculate(weight):
    pounds = validate_weight(weight)
    services = (
        ground_fee,
        express_air_fee,
        next_day_fee,
        fragile_handling_fee,
        heavy_surcharge,
        rural_delivery_fee,
        international_base_fee,
        signature_required_fee,
    )
    return [service(pounds) for service in services]


