def validate_data(data):
    if len(data) != 6:
        raise ValueError("expected 6 values: moles, mass solute, volume solute, mass solvent, volume solution, total moles")
    if any(value < 0 for value in data):
        raise ValueError("concentration inputs cannot be negative")
    return [float(value) for value in data]


def molarity(moles_solute, volume_solution_l):
    if volume_solution_l == 0:
        raise ZeroDivisionError("solution volume must be greater than zero")
    return moles_solute / volume_solution_l


def molality(moles_solute, mass_solvent_g):
    if mass_solvent_g == 0:
        raise ZeroDivisionError("solvent mass must be greater than zero")
    return moles_solute / (mass_solvent_g / 1000.0)


def mass_percentage(mass_solute_g, mass_solvent_g):
    total_mass = mass_solute_g + mass_solvent_g
    if total_mass == 0:
        raise ZeroDivisionError("total mass must be greater than zero")
    return 100.0 * mass_solute_g / total_mass


def volume_percentage(volume_solute_ml, volume_solution_l):
    if volume_solution_l == 0:
        raise ZeroDivisionError("solution volume must be greater than zero")
    return 100.0 * volume_solute_ml / (volume_solution_l * 1000.0)


def mole_fraction_solute(moles_solute, total_moles):
    if total_moles == 0:
        raise ZeroDivisionError("total moles must be greater than zero")
    return moles_solute / total_moles


def mole_fraction_solvent(moles_solute, total_moles):
    return 1.0 - mole_fraction_solute(moles_solute, total_moles)


def parts_per_million(mass_solute_g, mass_solvent_g):
    total_mass = mass_solute_g + mass_solvent_g
    if total_mass == 0:
        raise ZeroDivisionError("total mass must be greater than zero")
    return 1e6 * mass_solute_g / total_mass


def parts_per_billion(mass_solute_g, mass_solvent_g):
    return 1000.0 * parts_per_million(mass_solute_g, mass_solvent_g)


def solutions(data):
    moles, mass_solute, vol_solute, mass_solvent, vol_solution, total_moles = validate_data(data)
    return [
        molarity(moles, vol_solution),
        molality(moles, mass_solvent),
        mass_percentage(mass_solute, mass_solvent),
        volume_percentage(vol_solute, vol_solution),
        mole_fraction_solute(moles, total_moles),
        mole_fraction_solvent(moles, total_moles),
        parts_per_million(mass_solute, mass_solvent),
        parts_per_billion(mass_solute, mass_solvent),
    ]


def format_report(results):
    labels = ["Molarity (mol/L)", "Molality (mol/kg)", "Mass percentage (%)",
              "Volume percentage (%)", "Mole fraction of solute", "Mole fraction of solvent",
              "Parts per million", "Parts per billion"]
    lines = []
    for label, value in zip(labels, results):
        lines.append("{:<26}{:>16.6g}".format(label, value))
    return "\n".join(lines)


def main():
    sample = [2, 50, 20, 1000, 1.5, 50]
    print(format_report(solutions(sample)))


if __name__ == "__main__":
    main()

