def validate_population(population):
    if len(population) != 6:
        raise ValueError("expected six values: population, new, existing, deaths, disease deaths, multiplier")
    if any(not isinstance(value, int) for value in population):
        raise TypeError("all epidemiological inputs must be integers")
    total, new_cases, existing_cases, deaths, disease_deaths, multiplier = population
    if total <= 0 or multiplier <= 0:
        raise ValueError("population size and time period multiplier must be positive")
    if min(new_cases, existing_cases, deaths, disease_deaths) < 0:
        raise ValueError("counts of cases and deaths cannot be negative")
    if disease_deaths > deaths:
        raise ValueError("disease deaths cannot exceed total deaths")
    return population


def incidence_rate(total, new_cases, multiplier):
    population_at_risk = total - new_cases
    return new_cases / population_at_risk * multiplier


def prevalence_rate(total, new_cases, existing_cases, multiplier):
    return (new_cases + existing_cases) / total * multiplier


def point_prevalence(total, existing_cases, multiplier):
    return existing_cases / total * multiplier


def period_prevalence(total, new_cases, existing_cases, multiplier):
    return (existing_cases + new_cases) / total * multiplier


def case_fatality_rate(new_cases, existing_cases, disease_deaths):
    cases = new_cases + existing_cases
    if cases == 0:
        return 0.0
    return disease_deaths / cases * 100


def crude_mortality_rate(total, deaths, multiplier):
    return deaths / total * multiplier


def cause_specific_mortality_rate(total, disease_deaths, multiplier):
    return disease_deaths / total * multiplier


def proportional_mortality_ratio(deaths, disease_deaths):
    if deaths == 0:
        return 0.0
    return disease_deaths / deaths * 100


def outbreak(population):
    total, new_cases, existing_cases, deaths, disease_deaths, multiplier = validate_population(population)
    return [
        incidence_rate(total, new_cases, multiplier),
        prevalence_rate(total, new_cases, existing_cases, multiplier),
        point_prevalence(total, existing_cases, multiplier),
        period_prevalence(total, new_cases, existing_cases, multiplier),
        case_fatality_rate(new_cases, existing_cases, disease_deaths),
        crude_mortality_rate(total, deaths, multiplier),
        cause_specific_mortality_rate(total, disease_deaths, multiplier),
        proportional_mortality_ratio(deaths, disease_deaths),
    ]


def report(statistics, multiplier):
    labels = [
        "Incidence rate", "Prevalence rate", "Point prevalence", "Period prevalence",
        "Case fatality rate", "Crude mortality rate", "Cause specific mortality rate",
        "Proportional mortality ratio",
    ]
    units = ["%" if "fatality" in label or "Proportional" in label else f" per {multiplier}" for label in labels]
    return "\n".join(f"{label}: {value:.3f}{unit}" for label, value, unit in zip(labels, statistics, units))


def main():
    population = [100000, 500, 2000, 1000, 50, 100000]
    statistics = outbreak(population)
    print(report(statistics, population[5]))


if __name__ == "__main__":
    main()

