import math


NAMES = (
    "declination",
    "hour angle",
    "solar altitude",
    "solar zenith",
    "solar azimuth",
    "surface azimuth",
    "angle of incidence",
    "extraterrestrial radiation",
)


def clamp_cosine(value):
    return max(-1.0, min(1.0, value))


def declination_angle(day):
    return 23.45 * math.sin(math.radians(360.0 / 365.0 * (284 + day)))


def hour_angle(solar_time):
    return 15.0 * (solar_time - 12.0)


def solar_altitude_angle(declination, latitude, omega):
    d, phi, w = map(math.radians, (declination, latitude, omega))
    sin_alpha = math.sin(d) * math.sin(phi) + math.cos(d) * math.cos(phi) * math.cos(w)
    return math.degrees(math.asin(clamp_cosine(sin_alpha)))


def solar_zenith_angle(altitude):
    return 90.0 - altitude


def solar_azimuth_angle(declination, latitude, omega, zenith):
    d, phi, z = map(math.radians, (declination, latitude, zenith))
    denominator = math.sin(z) * math.cos(phi)
    if abs(denominator) < 1e-12:
        return 0.0
    cos_gamma = (math.cos(z) * math.sin(phi) - math.sin(d)) / denominator
    gamma = math.degrees(math.acos(clamp_cosine(cos_gamma)))
    return math.copysign(gamma, omega) if omega else gamma * 0.0


def surface_azimuth_angle(solar_azimuth, surface_orientation):
    difference = (solar_azimuth - surface_orientation + 180.0) % 360.0 - 180.0
    return difference


def angle_of_incidence(zenith, tilt, relative_azimuth):
    z, beta, gamma = map(math.radians, (zenith, tilt, relative_azimuth))
    cos_theta = math.cos(z) * math.cos(beta) + math.sin(z) * math.sin(beta) * math.cos(gamma)
    return math.degrees(math.acos(clamp_cosine(cos_theta)))


def extraterrestrial_radiation(day):
    return 1367.0 * (1.0 + 0.033 * math.cos(math.radians(360.0 * day / 365.0)))


def validate_parameters(parameters):
    if len(parameters) != 5:
        raise ValueError("expected [day, solar_time, latitude, tilt, surface_azimuth]")
    day, solar_time, latitude, tilt, azimuth = (float(value) for value in parameters)
    if not 1 <= day <= 366:
        raise ValueError("day of year must lie between 1 and 366")
    if not 0 <= solar_time <= 24:
        raise ValueError("local solar time must lie between 0 and 24 hours")
    if abs(latitude) > 90:
        raise ValueError("latitude must lie between -90 and 90 degrees")
    if not 0 <= tilt <= 90:
        raise ValueError("surface tilt must lie between 0 and 90 degrees")
    return int(day), solar_time, latitude, tilt, azimuth


def solar(parameters):
    day, solar_time, latitude, tilt, azimuth = validate_parameters(parameters)
    declination = declination_angle(day)
    omega = hour_angle(solar_time)
    altitude = solar_altitude_angle(declination, latitude, omega)
    zenith = solar_zenith_angle(altitude)
    solar_az = solar_azimuth_angle(declination, latitude, omega, zenith)
    relative_az = surface_azimuth_angle(solar_az, azimuth)
    incidence = angle_of_incidence(zenith, tilt, relative_az)
    radiation = extraterrestrial_radiation(day)
    return [declination, omega, altitude, zenith, solar_az, relative_az, incidence, radiation]


def format_report(results):
    units = ["deg"] * 7 + ["W/m^2"]
    lines = []
    for name, value, unit in zip(NAMES, results, units):
        lines.append("{:<28}{:>10.4f} {}".format(name, value, unit))
    return "\n".join(lines)


def main():
    parameters = [80, 12, 40, 30, 0]
    results = solar(parameters)
    print(results)
    print(format_report(results))


if __name__ == "__main__":
    main()

