import math

def cross_sectional_area(diameter):
    return math.pi * (diameter ** 2) / 4.0

def volumetric_flow_rate(mass, density, time):
    return mass / (density * time)

def flow_velocity(volumetric_rate, area):
    return volumetric_rate / area

def mass_flow_rate(mass, time):
    return mass / time

def reynolds_number(density, velocity, diameter, viscosity):
    return density * velocity * diameter / viscosity

def friction_factor(reynolds):
    if reynolds < 2300.0:
        return 64.0 / reynolds
    return 0.316 / (reynolds ** 0.25)

def head_loss(factor, length, diameter, velocity):
    return factor * (length / diameter) * (velocity ** 2) / (2.0 * 9.81)

def pressure_drop(density, loss):
    return density * 9.81 * loss

def validate(properties):
    if len(properties) != 6:
        raise ValueError("expected 6 parameters: diameter, density, viscosity, length, mass, time")
    if any(value <= 0 for value in properties):
        raise ValueError("all fluid parameters must be strictly positive")
    return [float(value) for value in properties]

def fluid(properties):
    diameter, density, viscosity, length, mass, time = validate(properties)
    area = cross_sectional_area(diameter)
    rate = volumetric_flow_rate(mass, density, time)
    velocity = flow_velocity(rate, area)
    mass_rate = mass_flow_rate(mass, time)
    reynolds = reynolds_number(density, velocity, diameter, viscosity)
    factor = friction_factor(reynolds)
    loss = head_loss(factor, length, diameter, velocity)
    drop = pressure_drop(density, loss)
    return [area, velocity, rate, mass_rate, reynolds, factor, loss, drop]

def report(metrics):
    labels = [
        ("Cross sectional area", "m^2"),
        ("Flow velocity", "m/s"),
        ("Volumetric flow rate", "m^3/s"),
        ("Mass flow rate", "kg/s"),
        ("Reynolds number", "-"),
        ("Friction factor", "-"),
        ("Head loss", "m"),
        ("Pressure drop", "Pa"),
    ]
    lines = []
    for (name, unit), value in zip(labels, metrics):
        lines.append("{:<22}{:>14.6g} {}".format(name, value, unit))
    return "\n".join(lines)

def main():
    water = [0.05, 998.0, 0.001, 1.0, 10.0, 5.0]
    metrics = fluid(water)
    print(metrics)
    print(report(metrics))


if __name__ == "__main__":
    main()

