R = 8.314462618


def validate_state(state):
    if len(state) != 6:
        raise ValueError("state must contain 6 values: p1, v1, t1, v2, gamma, n")
    p1, v1, t1, v2, gamma, n = (float(value) for value in state)
    if min(p1, v1, t1, v2, n) <= 0.0:
        raise ValueError("pressure, volumes, temperature and moles must be positive")
    if gamma <= 1.0:
        raise ValueError("heat capacity ratio must be greater than 1")
    return p1, v1, t1, v2, gamma, n


def boyles_law_final_pressure(p1, v1, v2):
    return p1 * v1 / v2


def charles_law_final_volume(v1, t1, t2):
    return v1 * t2 / t1


def gay_lussac_law_final_pressure(p1, t1, t2):
    return p1 * t2 / t1


def avogadro_law_total_moles(n1, v1, v2):
    return n1 * v2 / v1


def internal_energy_change(n, cv, delta_t):
    return n * cv * delta_t


def isobaric_work(p, v1, v2):
    return p * (v2 - v1)


def heat_transferred(n, cp, delta_t):
    return n * cp * delta_t


def adiabatic_final_temperature(t1, v1, v2, gamma):
    return t1 * (v1 / v2) ** (gamma - 1.0)


def thermodynamics(state):
    p1, v1, t1, v2, gamma, n = validate_state(state)
    cv = R / (gamma - 1.0)
    cp = gamma * cv
    t2 = adiabatic_final_temperature(t1, v1, v2, gamma)
    delta_t = t2 - t1
    return [
        boyles_law_final_pressure(p1, v1, v2),
        charles_law_final_volume(v1, t1, t2),
        gay_lussac_law_final_pressure(p1, t1, t2),
        avogadro_law_total_moles(n, v1, v2),
        internal_energy_change(n, cv, delta_t),
        isobaric_work(p1, v1, v2),
        heat_transferred(n, cp, delta_t),
        t2,
    ]


def format_report(results):
    labels = [
        ("Boyle final pressure", "Pa"),
        ("Charles final volume", "m^3"),
        ("Gay-Lussac final pressure", "Pa"),
        ("Avogadro total moles", "mol"),
        ("Internal energy change", "J"),
        ("Isobaric work", "J"),
        ("Heat transferred", "J"),
        ("Adiabatic final temperature", "K"),
    ]
    lines = []
    for (label, unit), value in zip(labels, results):
        lines.append("{:<30}{:>14.4f} {}".format(label, value, unit))
    return "\n".join(lines)


def main():
    stp_state = [101325.0, 0.0224140, 273.15, 0.0448280, 1.4, 1.0]
    print(format_report(thermodynamics(stp_state)))


if __name__ == "__main__":
    main()

