def safe_ratio(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def validate_matrix(matrix):
    if len(matrix) != 4:
        raise ValueError("matrix must contain exactly four counts")
    for count in matrix:
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError("counts must be integers")
        if count < 0:
            raise ValueError("counts must be non-negative")
    return tuple(matrix)


def true_positive_rate(tp, fp, fn, tn):
    return safe_ratio(tp, tp + fn)


def true_negative_rate(tp, fp, fn, tn):
    return safe_ratio(tn, tn + fp)


def positive_predictive_value(tp, fp, fn, tn):
    return safe_ratio(tp, tp + fp)


def negative_predictive_value(tp, fp, fn, tn):
    return safe_ratio(tn, tn + fn)


def false_positive_rate(tp, fp, fn, tn):
    return safe_ratio(fp, fp + tn)


def false_negative_rate(tp, fp, fn, tn):
    return safe_ratio(fn, fn + tp)


def false_discovery_rate(tp, fp, fn, tn):
    return safe_ratio(fp, fp + tp)


def false_omission_rate(tp, fp, fn, tn):
    return safe_ratio(fn, fn + tn)


def metric_routines():
    return [
        ("true positive rate", true_positive_rate),
        ("true negative rate", true_negative_rate),
        ("positive predictive value", positive_predictive_value),
        ("negative predictive value", negative_predictive_value),
        ("false positive rate", false_positive_rate),
        ("false negative rate", false_negative_rate),
        ("false discovery rate", false_discovery_rate),
        ("false omission rate", false_omission_rate),
    ]


def evaluate(matrix):
    tp, fp, fn, tn = validate_matrix(matrix)
    return [float(routine(tp, fp, fn, tn)) for _, routine in metric_routines()]


def format_report(matrix):
    values = evaluate(matrix)
    width = max(len(name) for name, _ in metric_routines())
    lines = ["counts: tp=%d fp=%d fn=%d tn=%d" % tuple(matrix)]
    for (name, _), value in zip(metric_routines(), values):
        lines.append("%-*s %8.4f" % (width, name, value))
    return "\n".join(lines)


def main():
    print(evaluate((10, 2, 3, 85)))
    print(format_report((10, 2, 3, 85)))
    print(format_report((0, 0, 4, 6)))


if __name__ == "__main__":
    main()

