def arrival_rate(total_arrivals, total_time):
    return total_arrivals / total_time


def service_rate(total_services, total_time):
    return total_services / total_time


def utilization(lam, mu):
    return lam / mu


def items_in_system(lam, mu):
    return lam / (mu - lam)


def items_in_queue(lam, mu):
    rho = utilization(lam, mu)
    return rho * items_in_system(lam, mu)


def time_in_system(lam, mu):
    return 1.0 / (mu - lam)


def time_in_queue(lam, mu):
    return utilization(lam, mu) * time_in_system(lam, mu)


def probability_empty(lam, mu):
    return 1.0 - utilization(lam, mu)


def validate(parameters):
    total_arrivals, total_time, total_services = parameters
    if total_time <= 0:
        raise ValueError("total time observed must be positive")
    if total_arrivals <= 0 or total_services <= 0:
        raise ValueError("arrival and service counts must be positive")
    if total_arrivals >= total_services:
        raise ValueError("system is unstable: arrivals must be fewer than services")
    return float(total_arrivals), float(total_time), float(total_services)


def analyze(parameters):
    total_arrivals, total_time, total_services = validate(parameters)
    lam = arrival_rate(total_arrivals, total_time)
    mu = service_rate(total_services, total_time)
    return [
        lam,
        mu,
        utilization(lam, mu),
        items_in_system(lam, mu),
        items_in_queue(lam, mu),
        time_in_system(lam, mu),
        time_in_queue(lam, mu),
        probability_empty(lam, mu),
    ]


def report(metrics):
    labels = [
        "Arrival rate (lambda)",
        "Service rate (mu)",
        "Utilization (rho)",
        "Items in system (L)",
        "Items in queue (Lq)",
        "Time in system (W)",
        "Time in queue (Wq)",
        "Probability empty (P0)",
    ]
    return "\n".join(
        "{:<24}{:>10.4f}".format(label, value)
        for label, value in zip(labels, metrics)
    )


def main():
    print(report(analyze((50, 10, 60))))


if __name__ == "__main__":
    main()

