def validate_twips(twips):
    if isinstance(twips, bool) or not isinstance(twips, (int, float)):
        raise TypeError("twips must be a numeric value")
    if twips < 0:
        raise ValueError("twips must not be negative")
    return float(twips)


def to_points(twips):
    return validate_twips(twips) / 20.0


def to_picas(twips):
    return to_points(twips) / 12.0


def to_inches(twips):
    return to_points(twips) / 72.0


def to_centimeters(twips):
    return to_inches(twips) * 2.54


def to_millimeters(twips):
    return to_centimeters(twips) * 10.0


def to_pixels(twips):
    return to_inches(twips) * 96.0


def to_ciceros(twips):
    return to_millimeters(twips) / 4.512


def to_didots(twips):
    return to_ciceros(twips) * 12.0


def conversion_routines():
    return [
        to_points,
        to_picas,
        to_inches,
        to_centimeters,
        to_millimeters,
        to_pixels,
        to_ciceros,
        to_didots,
    ]


def unit_names():
    return [
        "points",
        "picas",
        "inches",
        "centimeters",
        "millimeters",
        "pixels",
        "ciceros",
        "didots",
    ]


def scale(twips):
    return [float(routine(twips)) for routine in conversion_routines()]


def format_report(twips):
    lines = ["%g twips equals:" % validate_twips(twips)]
    for name, value in zip(unit_names(), scale(twips)):
        lines.append("  %14.6f %s" % (value, name))
    return "\n".join(lines)


def main():
    for sample in (1440, 720, 1, 0.5):
        print(format_report(sample))
    print(scale(1440))


if __name__ == "__main__":
    main()

