def _validate(frequency):
    if not isinstance(frequency, (int, float)) or isinstance(frequency, bool):
        raise TypeError("frequency must be a real number in hertz")
    if frequency <= 0:
        raise ValueError("frequency must be a positive number of hertz")
    return float(frequency)


def minor_second(frequency):
    return _validate(frequency) * 16 / 15


def major_second(frequency):
    return _validate(frequency) * 9 / 8


def minor_third(frequency):
    return _validate(frequency) * 6 / 5


def major_third(frequency):
    return _validate(frequency) * 5 / 4


def perfect_fourth(frequency):
    return _validate(frequency) * 4 / 3


def tritone(frequency):
    return _validate(frequency) * 45 / 32


def perfect_fifth(frequency):
    return _validate(frequency) * 3 / 2


def minor_sixth(frequency):
    return _validate(frequency) * 8 / 5


def pitch(frequency):
    root = _validate(frequency)
    return [
        minor_second(root),
        major_second(root),
        minor_third(root),
        major_third(root),
        perfect_fourth(root),
        tritone(root),
        perfect_fifth(root),
        minor_sixth(root),
    ]


def interval_names():
    return [
        "minor second",
        "major second",
        "minor third",
        "major third",
        "perfect fourth",
        "tritone",
        "perfect fifth",
        "minor sixth",
    ]


def format_report(frequency):
    lines = ["Root pitch: {0:.2f} Hz".format(_validate(frequency))]
    for name, value in zip(interval_names(), pitch(frequency)):
        lines.append("{0:<15}{1:>10.3f} Hz".format(name, value))
    return "\n".join(lines)


def main():
    for root in (440.0, 261.625565):
        print(format_report(root))
        print()


if __name__ == "__main__":
    main()

