def validate(batch):
    if len(batch) != 8:
        raise ValueError("batch must contain exactly eight values")
    values = [float(value) for value in batch]
    if any(value <= 0.0 for value in values):
        raise ValueError("all bath parameters must be positive")
    return values


def effective_surface_area(length, width, quantity):
    """Plated area in cm2 for flat parts wetted on both faces."""
    return 2.0 * length * width * quantity


def current_density(current, area):
    """Amperes per square decimetre of cathode surface."""
    return current / (area / 100.0)


def cathode_efficiency(density):
    """Fraction of current doing useful work, falling as density rises."""
    efficiency = 1.0 - 0.01 * density
    return min(1.0, max(0.5, efficiency))


def electrochemical_equivalent(molar_mass, valence):
    """Grams of metal released per coulomb, from Faraday's laws."""
    return molar_mass / (valence * 96485.0)


def total_plating_time(desired_mass, current, equivalent, efficiency):
    """Seconds needed to deposit the desired mass at this efficiency."""
    return desired_mass / (current * equivalent * efficiency)


def mass_deposited(current, seconds, equivalent, efficiency):
    """Actual grams laid down over the elapsed plating time."""
    return current * seconds * equivalent * efficiency


def expected_coating_thickness(mass, area):
    """Average coating thickness in micrometres for nickel-like metal."""
    return mass / (area * 8.9) * 10000.0


def tank_volume(desired_mass, quantity, concentration):
    """Litres of bath required to supply the metal for the whole load."""
    return desired_mass * quantity / concentration


def overall_current_efficiency(actual_mass, current, seconds, equivalent):
    """Deposited mass as a percentage of the theoretical Faraday yield."""
    theoretical = current * seconds * equivalent
    return actual_mass / theoretical * 100.0


def process(batch):
    current, length, width, quantity, molar_mass, valence, desired, conc = validate(batch)
    area = effective_surface_area(length, width, quantity)
    density = current_density(current, area)
    efficiency = cathode_efficiency(density)
    equivalent = electrochemical_equivalent(molar_mass, valence)
    seconds = total_plating_time(desired, current, equivalent, efficiency)
    deposited = mass_deposited(current, seconds, equivalent, efficiency)
    thickness = expected_coating_thickness(deposited, area)
    volume = tank_volume(desired, quantity, conc)
    overall = overall_current_efficiency(deposited, current, seconds, equivalent)
    return [density, seconds, thickness, efficiency, deposited,
            equivalent, area, volume, overall]

