import math

LABELS = (
    ("Solar heat gain", "W"),
    ("Conductive heat loss", "W"),
    ("Required ventilation rate", "m3/s"),
    ("Evaporative cooling potential", "W"),
    ("Supplemental heating demand", "kWh/day"),
    ("Vapor pressure deficit", "kPa"),
    ("CO2 injection rate", "g/h"),
    ("Daily light integral", "mol/m2/day"),
    ("Transpiration water loss", "L/day"),
)


def validate_inputs(greenhouse):
    if len(greenhouse) != 9:
        raise ValueError("greenhouse must contain nine numbers")
    values = []
    for item in greenhouse:
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("greenhouse values must be numbers")
        values.append(float(item))
    if not 0.0 <= values[5] <= 100.0:
        raise ValueError("relative humidity must be a percentage")
    return values


def solar_heat_gain(roof_area, irradiance):
    return roof_area * irradiance * 0.70


def conductive_heat_loss(roof_area, wall_area, t_in, t_out):
    return (roof_area * 6.0 + wall_area * 5.5) * (t_in - t_out)


def ventilation_rate(gain, loss, t_in, t_out):
    allowed_rise = max(t_in - t_out, 1.0)
    surplus = max(gain - loss, 0.0)
    return surplus / (1.2 * 1005.0 * allowed_rise)


def evaporative_cooling_potential(flow, t_in, rh):
    wet_bulb = (t_in * math.atan(0.151977 * math.sqrt(rh + 8.313659))
                + math.atan(t_in + rh) - math.atan(rh - 1.676331)
                + 0.00391838 * rh ** 1.5 * math.atan(0.023101 * rh) - 4.686035)
    return 1.2 * 1005.0 * flow * (t_in - wet_bulb) * 0.75


def supplemental_heating_demand(gain, loss, daylight_hours):
    night_hours = max(24.0 - daylight_hours, 0.0)
    daytime_deficit = max(loss - gain, 0.0)
    return (loss * night_hours + daytime_deficit * daylight_hours) / 1000.0


def vapor_pressure_deficit(t_in, rh):
    saturation = 0.6108 * math.exp(17.27 * t_in / (t_in + 237.3))
    return saturation * (1.0 - rh / 100.0)


def carbon_dioxide_injection_rate(roof_area, target_co2, current_co2):
    volume = roof_area * 3.5
    deficit = max(target_co2 - current_co2, 0.0)
    return volume * deficit * 1e-6 * 1830.0 * 1.75


def daily_light_integral(irradiance, daylight_hours):
    ppfd = irradiance * 0.70 * 2.02
    return ppfd * daylight_hours * 3600.0 / 1e6


def transpiration_water_loss(roof_area, irradiance, vpd, daylight_hours):
    net_radiation = 0.70 * irradiance * 0.5
    flux = 0.5 * net_radiation / 2450.0 + 0.0003 * 3.0 * vpd
    return flux * 3600.0 * daylight_hours * roof_area / 1000.0


def measure(greenhouse):
    (roof, wall, t_in, t_out, irradiance, rh,
     target_co2, current_co2, daylight) = validate_inputs(greenhouse)
    gain = solar_heat_gain(roof, irradiance)
    loss = conductive_heat_loss(roof, wall, t_in, t_out)
    flow = ventilation_rate(gain, loss, t_in, t_out)
    vpd = vapor_pressure_deficit(t_in, rh)
    return [gain, loss, flow,
            evaporative_cooling_potential(flow, t_in, rh),
            supplemental_heating_demand(gain, loss, daylight),
            vpd,
            carbon_dioxide_injection_rate(roof, target_co2, current_co2),
            daily_light_integral(irradiance, daylight),
            transpiration_water_loss(roof, irradiance, vpd, daylight)]


def format_report(results):
    return ["{0:<30}{1:>12.2f} {2}".format(name, value, unit)
            for (name, unit), value in zip(LABELS, results)]


def main():
    greenhouse = [500, 200, 22, 5, 600, 60, 1000, 400, 12]
    for line in format_report(measure(greenhouse)):
        print(line)


if __name__ == "__main__":
    main()

