def validate(beam):
    if len(beam) != 8:
        raise ValueError("beam must contain exactly eight numbers")
    if any(value <= 0 for value in beam[1:]):
        raise ValueError("only the length may be given as zero or negative is not allowed")
    return [float(value) for value in beam]


def cross_sectional_area(width, height):
    return width * height


def moment_of_inertia(width, height):
    return width * height ** 3 / 12.0


def max_bending_moment(length, point_load, distributed_load):
    return point_load * length / 4.0 + distributed_load * length ** 2 / 8.0


def max_shear_force(length, point_load, distributed_load):
    return point_load / 2.0 + distributed_load * length / 2.0


def bending_stress(moment, neutral_axis_distance, inertia):
    return moment * neutral_axis_distance / inertia


def shear_stress(shear, area):
    return 1.5 * shear / area


def max_deflection(length, point_load, distributed_load, modulus, inertia):
    point_term = point_load * length ** 3 / (48.0 * modulus * inertia)
    distributed_term = 5.0 * distributed_load * length ** 4 / (384.0 * modulus * inertia)
    return point_term + distributed_term


def section_modulus(inertia, neutral_axis_distance):
    return inertia / neutral_axis_distance


def factor_of_safety(yield_strength, stress):
    return yield_strength / stress


def analyze(beam):
    length, width, height, point_load, distributed_load, modulus, yield_strength, c = validate(beam)
    area = cross_sectional_area(width, height)
    inertia = moment_of_inertia(width, height)
    moment = max_bending_moment(length, point_load, distributed_load)
    shear = max_shear_force(length, point_load, distributed_load)
    sigma = bending_stress(moment, c, inertia)
    tau = shear_stress(shear, area)
    deflection = max_deflection(length, point_load, distributed_load, modulus, inertia)
    modulus_s = section_modulus(inertia, c)
    safety = factor_of_safety(yield_strength, sigma)
    return [area, inertia, moment, shear, sigma, tau, deflection, modulus_s, safety]


def report(results):
    labels = [
        "Cross sectional area (m^2)",
        "Moment of inertia (m^4)",
        "Maximum bending moment (N*m)",
        "Maximum shear force (N)",
        "Bending stress (Pa)",
        "Shear stress (Pa)",
        "Maximum deflection (m)",
        "Section modulus (m^3)",
        "Factor of safety",
    ]
    return "\n".join("%-30s %.6g" % (label, value) for label, value in zip(labels, results))


def main():
    beam = [5.0, 0.1, 0.2, 10000.0, 2000.0, 200e9, 250e6, 0.1]
    print(report(analyze(beam)))


if __name__ == "__main__":
    main()

