LATENT_HEAT_WATER = 2257.0
AIR_DENSITY = 1.2
AIR_SPECIFIC_HEAT = 1.005
HUMIDITY_PICKUP = 0.02
GAS_LHV = 37500.0
BAKE_RATE_MIN_PER_KG = 24.0


def validate(oven):
    if len(oven) != 9:
        raise ValueError("oven must hold nine parameters")
    values = [float(v) for v in oven]
    if min(values[:5]) <= 0 or values[7] <= 0 or values[8] <= 0:
        raise ValueError("lengths, masses, heat capacity and capacities must be positive")
    if values[3] >= values[2]:
        raise ValueError("baked mass must be lower than dough mass")
    if values[6] <= values[5]:
        raise ValueError("baking temperature must exceed entering temperature")
    return values


def total_baking_time(baked_mass):
    return BAKE_RATE_MIN_PER_KG * baked_mass


def conveyor_speed(oven_length, baking_time):
    return oven_length / baking_time


def piece_rate(speed, spacing):
    return speed / spacing


def total_heat_load(pieces_per_min, dough_mass, baked_mass, specific_heat, t_in, t_bake):
    sensible = dough_mass * specific_heat * (t_bake - t_in)
    latent = (dough_mass - baked_mass) * LATENT_HEAT_WATER
    return pieces_per_min * (sensible + latent) / 60.0


def moisture_loss_rate(pieces_per_min, dough_mass, baked_mass):
    return pieces_per_min * (dough_mass - baked_mass) * 60.0


def exhaust_airflow(moisture_per_hour):
    dry_air_mass = moisture_per_hour / HUMIDITY_PICKUP
    return dry_air_mass / AIR_DENSITY


def exhaust_heat_load(airflow, t_in, t_bake):
    mass_flow = airflow * AIR_DENSITY / 3600.0
    return mass_flow * AIR_SPECIFIC_HEAT * (t_bake - t_in)


def gas_consumption_rate(heat_load, exhaust_load, burner_capacity):
    firing_rate = heat_load + exhaust_load
    if firing_rate > burner_capacity:
        raise ValueError("required firing rate exceeds burner capacity")
    return firing_rate * 3600.0 / GAS_LHV


def product_output_rate(pieces_per_min, baked_mass):
    return pieces_per_min * baked_mass * 60.0


def thermal_efficiency(heat_load, gas_rate):
    return 100.0 * heat_load / (gas_rate * GAS_LHV / 3600.0)


def cooling_conveyor_length(speed, cooling_time):
    return speed * cooling_time


def analyze(oven):
    length, spacing, dough, baked, cp, t_in, t_bake, burner, cool_time = validate(oven)
    bake_time = total_baking_time(baked)
    speed = conveyor_speed(length, bake_time)
    pieces = piece_rate(speed, spacing)
    heat = total_heat_load(pieces, dough, baked, cp, t_in, t_bake)
    moisture = moisture_loss_rate(pieces, dough, baked)
    airflow = exhaust_airflow(moisture)
    gas = gas_consumption_rate(heat, exhaust_heat_load(airflow, t_in, t_bake), burner)
    return [bake_time, speed, heat, moisture, airflow, gas,
            product_output_rate(pieces, baked), thermal_efficiency(heat, gas),
            cooling_conveyor_length(speed, cool_time)]


def format_report(results):
    labels = [("Total baking time", "min"), ("Conveyor speed", "m/min"),
              ("Total heat load", "kW"), ("Moisture loss rate", "kg/h"),
              ("Exhaust airflow", "m3/h"), ("Gas consumption", "m3/h"),
              ("Product output", "kg/h"), ("Thermal efficiency", "%"),
              ("Cooling conveyor length", "m")]
    return "\n".join("%-25s %10.3f %s" % (name, value, unit)
                     for (name, unit), value in zip(labels, results))


def main():
    oven = [30, 0.5, 0.5, 0.45, 2.5, 20, 200, 500, 15]
    print(format_report(analyze(oven)))


if __name__ == "__main__":
    main()

