METRIC_LABELS = (
    "charge temperature (C)",
    "turning point (min)",
    "rate of rise (C/min)",
    "development time ratio",
    "first crack start (min)",
    "drop temperature (C)",
    "weight loss (%)",
    "roast level score",
    "cooling time (min)",
)

FIRST_CRACK_TEMP = 196.0


def validate_roast(roast):
    if len(roast) != 6:
        raise ValueError("roast must hold six readings")
    ambient, weight, heat, fan, peak, drop = roast
    if weight <= 0:
        raise ValueError("bean weight must be positive")
    if heat <= 0:
        raise ValueError("applied heat energy must be positive")
    if fan < 0:
        raise ValueError("fan speed cannot be negative")
    if peak <= ambient:
        raise ValueError("environmental peak must exceed ambient temperature")
    if drop <= 2:
        raise ValueError("drop time must exceed two minutes")
    return float(ambient), float(weight), float(heat), float(fan), float(peak), float(drop)


def charge_temperature(ambient, heat, peak):
    return round(peak - heat * 0.5 + ambient * 0.25, 2)


def turning_point_time(weight, fan):
    return round(0.6 + weight / 1000.0 * 0.5 + fan * 0.05, 2)


def rate_of_rise(charge, peak, turning, drop):
    return round((peak - charge) / (drop - turning), 3)


def first_crack_start_time(charge, turning, ror):
    if charge >= FIRST_CRACK_TEMP:
        return round(turning, 2)
    return round(turning + (FIRST_CRACK_TEMP - charge) / ror, 2)


def development_time_ratio(crack, drop):
    return round(max(drop - crack, 0.0) / drop, 3)


def drop_temperature(charge, ror, turning, drop, fan):
    return round(charge + ror * (drop - turning) - fan * 0.4, 2)


def weight_loss_percent(dtr, drop_temp):
    return round(8.0 + dtr * 12.0 + (drop_temp - 190.0) * 0.2, 2)


def roast_level_score(drop_temp, dtr):
    raw = (drop_temp - 180.0) / 50.0 * 100.0 + dtr * 40.0
    return round(min(max(raw, 0.0), 100.0), 1)


def cooling_time(drop_temp, ambient, fan):
    return round((drop_temp - ambient) / (8.0 + fan * 2.5), 2)


def profile(roast):
    ambient, weight, heat, fan, peak, drop = validate_roast(roast)
    charge = charge_temperature(ambient, heat, peak)
    turning = turning_point_time(weight, fan)
    ror = rate_of_rise(charge, peak, turning, drop)
    crack = first_crack_start_time(charge, turning, ror)
    dtr = development_time_ratio(crack, drop)
    drop_temp = drop_temperature(charge, ror, turning, drop, fan)
    loss = weight_loss_percent(dtr, drop_temp)
    score = roast_level_score(drop_temp, dtr)
    cooling = cooling_time(drop_temp, ambient, fan)
    return (charge, turning, ror, dtr, crack, drop_temp, loss, score, cooling)


def format_report(metrics):
    return "\n".join(
        "{:<26}{:>8}".format(label, value)
        for label, value in zip(METRIC_LABELS, metrics)
    )


def main():
    session = (22, 1000, 80, 5, 210, 12)
    metrics = profile(session)
    print("roast session:", session)
    print(format_report(metrics))
    print("profile tuple:", metrics)


if __name__ == "__main__":
    main()

