def validate_fragrance(fragrance):
    total, oil_ratio, top_fraction, heart_fraction, fixative_ratio, cost_per_ml = fragrance
    if total <= 0:
        raise ValueError("total target volume must be positive")
    if not 0 < oil_ratio <= 1:
        raise ValueError("essential oil ratio must be within (0, 1]")
    if top_fraction + heart_fraction > 1:
        raise ValueError("top and heart fractions exceed the oil blend")
    if oil_ratio + fixative_ratio + 0.03 > 1:
        raise ValueError("no room left for perfumers alcohol")
    if cost_per_ml < 0:
        raise ValueError("base cost per millilitre cannot be negative")
    return fragrance


def essential_oil_volume(total, oil_ratio):
    return round(total * oil_ratio, 2)


def top_note_volume(oil_volume, top_fraction):
    return round(oil_volume * top_fraction, 2)


def heart_note_volume(oil_volume, heart_fraction):
    return round(oil_volume * heart_fraction, 2)


def base_note_volume(oil_volume, top_fraction, heart_fraction):
    return round(oil_volume * (1 - top_fraction - heart_fraction), 2)


def fixative_amount(total, fixative_ratio):
    return round(total * fixative_ratio, 2)


def distilled_water_addition(total):
    return round(total * 0.03, 2)


def perfumers_alcohol(total, oil_volume, fixative, water):
    return round(total - oil_volume - fixative - water, 2)


def concentration_percentage(total, oil_volume):
    return round(oil_volume / total * 100, 2)


def maceration_days(concentration, fixative):
    return round(14 + concentration * 0.5 + fixative * 0.4, 1)


def batch_cost(oil_volume, alcohol, fixative, cost_per_ml):
    oils = oil_volume * cost_per_ml * 4
    carrier = alcohol * cost_per_ml * 0.2
    binder = fixative * cost_per_ml * 1.5
    return round(oils + carrier + binder, 2)


def blend(fragrance):
    total, oil_ratio, top_f, heart_f, fix_ratio, cost_per_ml = validate_fragrance(fragrance)
    oil_volume = essential_oil_volume(total, oil_ratio)
    top = top_note_volume(oil_volume, top_f)
    heart = heart_note_volume(oil_volume, heart_f)
    base = base_note_volume(oil_volume, top_f, heart_f)
    fixative = fixative_amount(total, fix_ratio)
    water = distilled_water_addition(total)
    alcohol = perfumers_alcohol(total, oil_volume, fixative, water)
    concentration = concentration_percentage(total, oil_volume)
    days = maceration_days(concentration, fixative)
    cost = batch_cost(oil_volume, alcohol, fixative, cost_per_ml)
    return (top, heart, base, alcohol, fixative, water, concentration, days, cost)


def format_report(metrics):
    labels = ("top notes (ml)", "heart notes (ml)", "base notes (ml)",
              "perfumers alcohol (ml)", "fixative (ml)", "distilled water (ml)",
              "concentration (%)", "maceration (days)", "batch cost")
    return "\n".join("{:<24}{:>8}".format(name, value)
                     for name, value in zip(labels, metrics))


def main():
    formulation = (100, 0.2, 0.3, 0.5, 0.05, 2.5)
    print(format_report(blend(formulation)))


if __name__ == "__main__":
    main()

