import math

def validate_boat(boat):
    if len(boat) != 6:
        raise ValueError("a boat record needs six fields")
    start, finish, handicap, distance, wind, flags = boat
    if finish <= start:
        raise ValueError("finish time must be after start time")
    if handicap <= 0 or distance <= 0:
        raise ValueError("handicap rating and course distance must be positive")
    if flags < 0:
        raise ValueError("penalty flags cannot be negative")
    return start, finish, handicap, distance, wind % 360, flags


def elapsed_time(start, finish):
    return finish - start


def corrected_time(elapsed, handicap):
    return elapsed * handicap


def average_speed(distance, elapsed):
    return distance / (elapsed / 3600.0)


def port_tack_distance(distance, wind_direction):
    share = 0.5 + math.sin(math.radians(wind_direction)) / 4.0
    return distance * share


def starboard_tack_distance(distance, wind_direction):
    return distance - port_tack_distance(distance, wind_direction)


def penalty_time(flags):
    return flags * 30.0


def mark_rounding_efficiency(elapsed, penalty):
    return elapsed / (elapsed + penalty) * 100.0


def downwind_angle(wind_direction):
    return (wind_direction + 180) % 360


def race_points(corrected, penalty):
    return (corrected + penalty) / 3600.0


def score(boat):
    start, finish, handicap, distance, wind, flags = validate_boat(boat)
    elapsed = elapsed_time(start, finish)
    corrected = corrected_time(elapsed, handicap)
    penalty = penalty_time(flags)
    return [elapsed, round(corrected, 2),
            round(average_speed(distance, elapsed), 2),
            round(port_tack_distance(distance, wind), 2),
            round(starboard_tack_distance(distance, wind), 2),
            penalty, round(mark_rounding_efficiency(elapsed, penalty), 2),
            downwind_angle(wind), round(race_points(corrected, penalty), 3)]


def format_report(name, metrics):
    labels = ["elapsed", "corrected", "avg speed", "port dist", "stbd dist",
              "penalty", "mark eff", "downwind", "points"]
    body = ", ".join("%s=%s" % pair for pair in zip(labels, metrics))
    return "%-10s %s" % (name, body)


def main():
    fleet = [("Windswept", [3600, 7200, 0.95, 12, 180, 1]),
             ("Sea Fever", [3550, 7410, 1.02, 12, 225, 0]),
             ("Kestrel", [3600, 7900, 0.88, 12, 45, 3])]
    results = [(name, score(record)) for name, record in fleet]
    for name, metrics in sorted(results, key=lambda item: item[1][-1]):
        print(format_report(name, metrics))


if __name__ == "__main__":
    main()

