def validate_joint(joint):
    density, thickness, width, force, glue = joint
    if min(density, thickness, width, glue) <= 0:
        raise ValueError("density, dimensions and glue strength must be positive")
    if force < 0:
        raise ValueError("applied force cannot be negative")
    if thickness > width:
        raise ValueError("board thickness cannot exceed board width")
    return density, thickness, width, force, glue


def tenon_thickness(board_thickness):
    return board_thickness / 3.0


def tenon_width(board_width):
    return board_width * 0.75


def tenon_length(board_thickness):
    return 5.0 * tenon_thickness(board_thickness)


def glue_surface_area(board_thickness, board_width):
    length = tenon_length(board_thickness)
    return 2.0 * length * (tenon_width(board_width) + tenon_thickness(board_thickness))


def shear_strength(board_thickness, board_width, glue_strength):
    return glue_surface_area(board_thickness, board_width) * glue_strength


def bending_moment_capacity(density, board_thickness, board_width):
    section_modulus = tenon_width(board_width) * tenon_thickness(board_thickness) ** 2 / 6.0
    fibre_stress = density * 0.08
    return section_modulus * fibre_stress / 1000.0


def pullout_resistance(board_thickness, board_width, glue_strength):
    faces = 2.0 * tenon_length(board_thickness) * tenon_width(board_width)
    return faces * glue_strength * 0.6


def wood_compression_factor(density):
    factor = density / 600.0
    return min(max(factor, 0.5), 1.8)


def joint_safety_factor(joint):
    density, thickness, width, force, glue = joint
    capacity = shear_strength(thickness, width, glue) * wood_compression_factor(density)
    if force == 0:
        return float("inf")
    return capacity / force


def test(joint):
    density, thickness, width, force, glue = validate_joint(joint)
    values = [
        tenon_thickness(thickness),
        tenon_width(width),
        tenon_length(thickness),
        glue_surface_area(thickness, width),
        shear_strength(thickness, width, glue),
        bending_moment_capacity(density, thickness, width),
        pullout_resistance(thickness, width, glue),
        wood_compression_factor(density),
        joint_safety_factor((density, thickness, width, force, glue)),
    ]
    return [round(v, 2) for v in values]


def format_report(joint):
    labels = ["tenon thickness (mm)", "tenon width (mm)", "tenon length (mm)",
              "glue surface area (mm^2)", "shear strength (N)",
              "bending moment capacity (Nm)", "pullout resistance (N)",
              "wood compression factor", "safety factor"]
    results = test(joint)
    lines = ["Mortise and tenon joint %s" % (joint,)]
    for label, value in zip(labels, results):
        lines.append("  %-28s %10.2f" % (label, value))
    return "\n".join(lines)


def main():
    print(format_report((600, 20, 50, 1500, 8)))
    print(format_report((450, 25, 80, 2200, 6)))


if __name__ == "__main__":
    main()

