from math import exp

EFFICIENCY = 0.75
GRAIN_POINTS = 308.0
GRAIN_ABSORPTION = 0.9
BOIL_OFF_RATE = 3.0
TRUB_LOSS = 1.0
APPARENT_ATTENUATION = 0.75
PITCH_RATE = 0.75e6

LABELS = ("Grain weight (kg)", "Strike water (L)", "Sparge water (L)",
          "Pre-boil wort (L)", "Estimated OG", "Bitterness (IBU)",
          "Yeast cells (billion)", "Final gravity", "ABV (%)")


def total_grain_weight(batch_volume, original_gravity):
    points = (original_gravity - 1.0) * 1000.0 * batch_volume
    return points / (GRAIN_POINTS * EFFICIENCY)


def mash_strike_volume(grain_weight, thickness):
    return grain_weight * thickness


def pre_boil_wort_volume(batch_volume, boil_time):
    return batch_volume + TRUB_LOSS + BOIL_OFF_RATE * boil_time / 60.0


def sparge_water_volume(grain_weight, strike_volume, preboil_volume):
    runoff = strike_volume - grain_weight * GRAIN_ABSORPTION
    return max(0.0, preboil_volume - runoff)


def estimated_original_gravity(grain_weight, batch_volume):
    points = grain_weight * GRAIN_POINTS * EFFICIENCY / batch_volume
    return 1.0 + points / 1000.0


def boil_gravity(original_gravity, batch_volume, preboil_volume):
    return 1.0 + (original_gravity - 1.0) * batch_volume / preboil_volume


def hop_bitterness_units(hop_weight, alpha_acid, boil_time, volume, gravity):
    utilisation = (1.65 * 0.000125 ** (gravity - 1.0)
                   * (1.0 - exp(-0.04 * boil_time)) / 4.15)
    return hop_weight * utilisation * (alpha_acid / 100.0) * 1000.0 / volume


def yeast_cell_requirement(batch_volume, original_gravity):
    plato = (original_gravity - 1.0) * 1000.0 / 4.0
    return PITCH_RATE * batch_volume * 1000.0 * plato


def expected_final_gravity(original_gravity):
    return 1.0 + (original_gravity - 1.0) * (1.0 - APPARENT_ATTENUATION)


def alcohol_by_volume(original_gravity, final_gravity):
    return (original_gravity - final_gravity) * 131.25


def brew(recipe):
    batch_volume, target_og, thickness, boil_time, alpha_acid, hop_weight = recipe
    grain = total_grain_weight(batch_volume, target_og)
    strike = mash_strike_volume(grain, thickness)
    preboil = pre_boil_wort_volume(batch_volume, boil_time)
    sparge = sparge_water_volume(grain, strike, preboil)
    og = estimated_original_gravity(grain, batch_volume)
    ibu = hop_bitterness_units(hop_weight, alpha_acid, boil_time, preboil,
                               boil_gravity(og, batch_volume, preboil))
    cells = yeast_cell_requirement(batch_volume, og)
    fg = expected_final_gravity(og)
    return [round(grain, 2), round(strike, 2), round(sparge, 2),
            round(preboil, 2), round(og, 3), round(ibu, 1),
            round(cells / 1e9, 1), round(fg, 3),
            round(alcohol_by_volume(og, fg), 2)]


def format_report(metrics):
    return "\n".join("%-22s %s" % (name, value)
                     for name, value in zip(LABELS, metrics))


def main():
    recipe = (20, 1.050, 3, 60, 5.5, 30)
    print(format_report(brew(recipe)))


if __name__ == "__main__":
    main()

