def require(data, *keys):
    missing = [key for key in keys if key not in data]
    if missing:
        raise ValueError("missing fields: " + ", ".join(missing))
    return tuple(data[key] for key in keys)


def carbon_nitrogen_ratio(data):
    green_weight, green_ratio, brown_weight, brown_ratio = require(
        data, "green_weight", "green_ratio", "brown_weight", "brown_ratio")
    total = green_weight + brown_weight
    if total <= 0:
        raise ValueError("no feedstock supplied")
    carbon = green_weight * green_ratio + brown_weight * brown_ratio
    return round(carbon / total, 2)


def moisture_content(data):
    wet_weight, dry_weight = require(data, "wet_weight", "dry_weight")
    if wet_weight <= 0 or dry_weight > wet_weight:
        raise ValueError("inconsistent wet and dry weights")
    return round((wet_weight - dry_weight) / wet_weight * 100.0, 1)


def temperature_profile(data):
    readings = require(data, "daily_temps")[0]
    if not readings:
        raise ValueError("no temperature readings")
    thermophilic = [temp for temp in readings if temp >= 55.0]
    return {
        "peak": max(readings),
        "average": round(sum(readings) / len(readings), 1),
        "thermophilic_days": len(thermophilic),
    }


def oxygen_level(data):
    porosity, volume = require(data, "porosity", "volume")
    free_air = porosity * volume
    airflow = free_air * 0.6
    return {"free_air_space": round(free_air, 2), "airflow_m3_per_h": round(airflow, 2)}


def pile_volume(data):
    initial, shrinkage, days = require(data, "initial_volume", "shrinkage_rate", "days")
    remaining = initial * (1.0 - shrinkage) ** (days / 7.0)
    return round(remaining, 2)


def turning_frequency(data):
    readings, threshold = require(data, "daily_temps", "threshold")
    turnings = sum(1 for temp in readings if temp < threshold)
    if turnings == 0:
        return {"turnings": 0, "interval_days": None}
    return {"turnings": turnings, "interval_days": round(len(readings) / turnings, 1)}


def particle_size(data):
    diameter, mass = require(data, "diameter_mm", "mass_kg")
    if diameter <= 0:
        raise ValueError("diameter must be positive")
    radius = diameter / 2000.0
    particle_volume = 4.0 / 3.0 * 3.141592653589793 * radius ** 3
    particle_area = 4.0 * 3.141592653589793 * radius ** 2
    count = mass / (particle_volume * 600.0)
    return round(count * particle_area / mass, 2)


def bulk_density(data):
    mass, volume = require(data, "mass_kg", "volume")
    if volume <= 0:
        raise ValueError("volume must be positive")
    density = mass / volume
    return {"density": round(density, 1), "compacted": density > 650.0}


def maturity_index(data):
    ammonia, nitrate = require(data, "ammonia_mg_kg", "nitrate_mg_kg")
    if nitrate <= 0:
        raise ValueError("nitrate must be positive")
    ratio = ammonia / nitrate
    return {"ratio": round(ratio, 3), "mature": ratio < 0.16}


def monitor(metric, data):
    table = {
        "carbon nitrogen ratio": carbon_nitrogen_ratio,
        "moisture content": moisture_content,
        "temperature profile": temperature_profile,
        "oxygen level": oxygen_level,
        "pile volume": pile_volume,
        "turning frequency": turning_frequency,
        "particle size": particle_size,
        "bulk density": bulk_density,
        "maturity index": maturity_index,
    }
    key = metric.strip().lower()
    if key not in table:
        raise KeyError("unknown metric: " + metric)
    return table[key](data)


def format_report(metric, result):
    if isinstance(result, dict):
        body = ", ".join("%s=%s" % (name, value) for name, value in result.items())
    else:
        body = str(result)
    return "%-24s %s" % (metric + ":", body)


def main():
    temps = [42.0, 58.5, 64.0, 61.2, 52.8, 49.5, 55.1]
    jobs = [
        ("carbon nitrogen ratio", {"green_weight": 400.0, "green_ratio": 18.0,
                                   "brown_weight": 600.0, "brown_ratio": 52.0}),
        ("moisture content", {"wet_weight": 120.0, "dry_weight": 48.0}),
        ("temperature profile", {"daily_temps": temps}),
        ("oxygen level", {"porosity": 0.35, "volume": 24.0}),
        ("pile volume", {"initial_volume": 24.0, "shrinkage_rate": 0.08, "days": 28}),
        ("turning frequency", {"daily_temps": temps, "threshold": 55.0}),
        ("particle size", {"diameter_mm": 12.0, "mass_kg": 1000.0}),
        ("bulk density", {"mass_kg": 15600.0, "volume": 24.0}),
        ("maturity index", {"ammonia_mg_kg": 62.0, "nitrate_mg_kg": 480.0}),
    ]
    for metric, payload in jobs:
        print(format_report(metric, monitor(metric, payload)))
    hydration = monitor("moisture content", {"wet_weight": 120.0, "dry_weight": 48.0})
    print("hydration percentage: %.1f%%" % hydration)


if __name__ == "__main__":
    main()

