def percentage(part, whole):
    if whole <= 0:
        raise ValueError("denominator must be positive, got %r" % (whole,))
    return round(100.0 * part / whole, 1)


def points(goals, assists):
    return goals + assists


def shooting_percentage(goals, shots):
    return percentage(goals, shots)


def goals_against_average(goals_against, minutes_played):
    if minutes_played <= 0:
        raise ValueError("minutes played must be positive")
    return round(goals_against * 60.0 / minutes_played, 2)


def save_percentage(saves, shots_against):
    return percentage(saves, shots_against)


def plus_minus(rating):
    return int(rating)


def faceoff_win_rate(won, lost):
    return percentage(won, won + lost)


def penalty_kill_rate(times_shorthanded, power_play_goals_against):
    return percentage(times_shorthanded - power_play_goals_against, times_shorthanded)


def power_play_rate(power_play_goals, power_play_opportunities):
    return percentage(power_play_goals, power_play_opportunities)


def overtime_points(overtime_goals, overtime_assists):
    return overtime_goals + overtime_assists


def metric_table():
    routines = (points, shooting_percentage, goals_against_average, save_percentage,
                plus_minus, faceoff_win_rate, penalty_kill_rate, power_play_rate,
                overtime_points)
    return dict((r.__name__, (r, 1 if r is plus_minus else 2)) for r in routines)


def analyze(data):
    numbers, metrics = data
    table = metric_table()
    results = []
    position = 0
    for name in metrics:
        if name not in table:
            raise ValueError("unknown metric: %s" % name)
        routine, arity = table[name]
        arguments = numbers[position:position + arity]
        if len(arguments) < arity:
            raise ValueError("not enough raw numbers for metric %s" % name)
        results.append(routine(*arguments))
        position += arity
    return results


def main():
    for data in (([20, 10, 5], ["points", "plus_minus"]),
                 ([18, 900, 432, 450], ["goals_against_average", "save_percentage"])):
        for name, value in zip(data[1], analyze(data)):
            print("%s: %s" % (name.replace("_", " "), value))


if __name__ == "__main__":
    main()

