    contested = match["objectives_taken"] + match["objectives_conceded"]
    return match["objectives_taken"] / contested if contested else 0.0

def damage_mitigated(match):
    return float(match["damage_self_mitigated"] + match["damage_shielded"])

def healing_per_minute(match):
    return match["healing_done"] / match_minutes(match)


ROUTINES = {f.__name__: f for f in (
    kill_death_assist_ratio, creep_score_per_minute, gold_per_minute,
    damage_per_minute, kill_participation, vision_score_per_minute,
    objective_control_rate, damage_mitigated, healing_per_minute,
)}

def profile(match):
    targets = match["targets"]
    unknown = [name for name in targets if name not in ROUTINES]
    if unknown:
        raise KeyError("unknown metric targets: %s" % ", ".join(unknown))
    return tuple(round(ROUTINES[name](match), 2) for name in targets)

def metric_label(name):
    return name.replace("_per_minute", "/min").replace("_", " ").capitalize()

def main():
    match = {"kills": 5, "deaths": 2, "assists": 4, "team_kills": 18, "creep_score": 284,
             "gold_earned": 13400, "damage_to_champions": 22600, "vision_score": 31,
             "objectives_taken": 7, "objectives_conceded": 3, "damage_self_mitigated": 18900,
             "damage_shielded": 1200, "healing_done": 4300, "duration_seconds": 1860,
             "targets": list(ROUTINES)}
    for name, value in zip(match["targets"], profile(match)):
        print("%-24s %s" % (metric_label(name), value))


if __name__ == "__main__":
    main()

