def validate_height(height):
    if not isinstance(height, (int, float)):
        raise TypeError("trunk height must be a number in centimetres")
    if height <= 0:
        raise ValueError("trunk height must be greater than zero")
    return float(height)


def formal_upright(height):
    return round(validate_height(height) * 0.40, 1)


def informal_upright(height):
    return round(validate_height(height) / 3.0, 1)


def slanting(height):
    return round(validate_height(height) * 0.35, 1)


def cascade(height):
    return round(validate_height(height) * 0.50, 1)


def semi_cascade(height):
    return round(validate_height(height) * 0.45, 1)


def literati(height):
    return round(validate_height(height) * 0.25, 1)


def windswept(height):
    return round(validate_height(height) * 0.30, 1)


def twin_trunk(height):
    return round(validate_height(height) * 0.38, 1)


def root_over_rock(height):
    return round(validate_height(height) * 0.32, 1)


def normalise_name(name):
    return "_".join(str(name).strip().lower().replace("-", " ").split())


def routines():
    return {
        "formal_upright": formal_upright,
        "informal_upright": informal_upright,
        "slanting": slanting,
        "cascade": cascade,
        "semi_cascade": semi_cascade,
        "literati": literati,
        "windswept": windswept,
        "twin_trunk": twin_trunk,
        "root_over_rock": root_over_rock,
    }


def style(height, styles):
    available = routines()
    lengths = []
    for requested in styles:
        key = normalise_name(requested)
        if key not in available:
            raise KeyError("unknown bonsai style: %s" % requested)
        lengths.append(available[key](height))
    return lengths


def format_report(height, styles):
    lengths = style(height, styles)
    header = "Trunk height: %.1f cm" % validate_height(height)
    rows = [header]
    for name, length in zip(styles, lengths):
        rows.append("  %-18s first branch %5.1f cm" % (normalise_name(name), length))
    return "\n".join(rows)


def main():
    print(format_report(30, ["informal upright", "cascade", "literati"]))
    print(format_report(75, ["Formal-Upright", "windswept", "root over rock"]))
    print(format_report(48, ["slanting", "semi cascade", "twin trunk"]))


if __name__ == "__main__":
    main()

