BOARD_NUMBERS = frozenset(range(1, 21))
BULL_NUMBER = 25


def validate_segment(number):
    if number not in BOARD_NUMBERS:
        raise ValueError(f"{number} is not a numbered board segment")
    return number


def validate_bull(number):
    if number != BULL_NUMBER:
        raise ValueError(f"the bullseye is numbered {BULL_NUMBER}, got {number}")
    return number


def single_bull(number):
    return validate_bull(number)


def double_bull(number):
    return 2 * validate_bull(number)


def single_segment(number):
    return validate_segment(number)


def double_ring(number):
    return 2 * validate_segment(number)


def treble_ring(number):
    return 3 * validate_segment(number)


def missed_dart(number):
    if number is not None:
        raise ValueError("a missed dart does not land on a number")
    return 0


def bust_score(number):
    validate_segment(number)
    return 0


def double_out(number):
    if number == BULL_NUMBER:
        return 2 * number
    return 2 * validate_segment(number)


def treble_setup(number):
    return 3 * validate_segment(number)


def routine_for(area):
    routines = {
        "single bull": single_bull,
        "double bull": double_bull,
        "single segment": single_segment,
        "double ring": double_ring,
        "treble ring": treble_ring,
        "missed dart": missed_dart,
        "bust score": bust_score,
        "double out": double_out,
        "treble setup": treble_setup,
    }
    if area not in routines:
        raise ValueError(f"unknown board area: {area}")
    return routines[area]


def checkout(darts):
    return [routine_for(area)(number) for area, number in darts]


def format_report(darts, points):
    lines = []
    for (area, number), scored in zip(darts, points):
        landed = "-" if number is None else str(number)
        lines.append(f"{landed:>3} in {area:<15} -> {scored:>3}")
    lines.append(f"{'total':>22} {sum(points):>3}")
    return "\n".join(lines)


def main():
    darts = [
        ("treble ring", 20),
        ("single segment", 5),
        ("double bull", 25),
        ("missed dart", None),
        ("treble setup", 17),
        ("bust score", 19),
        ("single bull", 25),
        ("double ring", 12),
        ("double out", 8),
    ]
    print(format_report(darts, checkout(darts)))


if __name__ == "__main__":
    main()

