def within(value, target, tolerance):
    return value is not None and abs(value - target) <= tolerance


def normalize(measurements):
    if not isinstance(measurements, dict):
        raise TypeError("measurements must be a mapping of dimension names to values")
    reading = {"style": measurements.get("style")}
    for field in ("thread_diameter_mm", "pin_spacing_mm", "base_length_mm"):
        value = measurements.get(field)
        if value is not None and not isinstance(value, (int, float)):
            raise TypeError("%s must be numeric or omitted" % field)
        reading[field] = value
    return reading


def threaded(m, diameter, diameter_tol, length, length_tol):
    return (m["style"] == "threaded"
            and within(m["thread_diameter_mm"], diameter, diameter_tol)
            and within(m["base_length_mm"], length, length_tol))


def bipin(m, spacing, spacing_tol, length, length_tol):
    return (m["style"] == "bipin"
            and within(m["pin_spacing_mm"], spacing, spacing_tol)
            and within(m["base_length_mm"], length, length_tol))


def tube(m, spacing, spacing_tol, diameter, diameter_tol):
    return (m["style"] == "bipin-tube"
            and within(m["pin_spacing_mm"], spacing, spacing_tol)
            and within(m["thread_diameter_mm"], diameter, diameter_tol))


def check_standard_edison(m):
    return threaded(m, 26.0, 0.6, 25.0, 3.0)


def check_candelabra(m):
    return threaded(m, 12.0, 0.4, 18.0, 2.5)


def check_intermediate(m):
    return threaded(m, 17.0, 0.4, 21.0, 2.5)


def check_mogul(m):
    return threaded(m, 39.0, 0.8, 44.0, 4.0)


def check_bipin_gu_ten(m):
    return bipin(m, 10.0, 0.3, 12.0, 1.5)


def check_bipin_mr_sixteen(m):
    return bipin(m, 5.3, 0.2, 10.0, 1.5)


def check_bipin_g_nine(m):
    return bipin(m, 9.0, 0.3, 8.0, 1.5)


def check_tube_t_eight(m):
    return tube(m, 13.0, 0.3, 26.0, 0.8)


def check_tube_t_five(m):
    return tube(m, 5.0, 0.2, 16.0, 0.6)


ROUTINES = (check_standard_edison, check_candelabra, check_intermediate, check_mogul, check_bipin_gu_ten,
            check_bipin_mr_sixteen, check_bipin_g_nine, check_tube_t_eight, check_tube_t_five)


def verify(measurements):
    reading = normalize(measurements)
    for check in ROUTINES:
        if check(reading):
            return check.__name__[len("check_"):].replace("_", " ")
    return None

