CATEGORY_NAMES = (
    "transport",
    "diet",
    "electricity",
    "heating",
    "waste",
    "water heating",
    "clothing",
    "internet",
)


def transport_footprint(miles_driven):
    return miles_driven * 0.4


def diet_footprint(meals):
    return meals * 2.5 + meals * 1.2


def electricity_footprint(kilowatt_hours):
    return kilowatt_hours * 0.9


def heating_footprint(hours_heated):
    return hours_heated * 1.5


def waste_footprint(pounds_of_trash):
    return pounds_of_trash * 0.5


def water_heating_footprint(minutes_showered):
    return minutes_showered * 0.2


def clothing_footprint(new_items):
    return new_items * 5


def internet_footprint(hours_streamed):
    return hours_streamed * 0.1


def validate_activities(activities):
    values = list(activities)
    if len(values) != len(CATEGORY_NAMES):
        raise ValueError("expected %d activity values" % len(CATEGORY_NAMES))
    for name, value in zip(CATEGORY_NAMES, values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s value must be a number" % name)
        if value < 0:
            raise ValueError("%s value must not be negative" % name)
    return values


def footprint(activities):
    values = validate_activities(activities)
    calculators = (
        transport_footprint,
        diet_footprint,
        electricity_footprint,
        heating_footprint,
        waste_footprint,
        water_heating_footprint,
        clothing_footprint,
        internet_footprint,
    )
    parts = tuple(calc(value) for calc, value in zip(calculators, values))
    return parts + (sum(parts),)


def format_report(activities):
    result = footprint(activities)
    lines = []
    for name, amount in zip(CATEGORY_NAMES, result[:-1]):
        lines.append("%-14s %8.2f kg" % (name, amount))
    lines.append("%-14s %8.2f kg" % ("total", result[-1]))
    return "\n".join(lines)


def main():
    print(format_report([10, 10, 10, 10, 10, 10, 10, 10]))
    print()
    print(format_report([24, 3, 8.5, 2, 4, 12, 0, 6]))


if __name__ == "__main__":
    main()

