def morning_mode(outside):
    return outside + 5, 80


def day_mode(outside):
    return outside - 10, 0


def evening_mode(outside):
    return outside + 3, 60


def night_mode(outside):
    return outside - 5, 10


def away_mode(outside):
    return 50, 0


def vacation_mode(outside):
    return 45, 50


def party_mode(outside):
    return outside - 15, 100


def emergency_mode(outside):
    return 100, 100


def mode_handler(mode):
    handlers = (
        morning_mode,
        day_mode,
        evening_mode,
        night_mode,
        away_mode,
        vacation_mode,
        party_mode,
        emergency_mode,
    )
    if not 1 <= mode <= len(handlers):
        raise ValueError("mode must be an integer from 1 to 8")
    return handlers[mode - 1]


def mode_name(mode):
    names = (
        "Morning", "Day", "Evening", "Night",
        "Away", "Vacation", "Party", "Emergency",
    )
    return names[mode - 1]


def validate_environment(environment):
    try:
        outside = float(environment["outside"])
        mode = int(environment["mode"])
    except KeyError as missing:
        raise ValueError("environment needs %s" % missing)
    except (TypeError, ValueError):
        raise ValueError("outside temperature and mode must be numeric")
    return outside, mode


def automate(environment):
    outside, mode = validate_environment(environment)
    return mode_handler(mode)(outside)


