def occupancy_rate(rooms_sold, rooms_available):
    return rooms_sold / rooms_available


def average_daily_rate(room_revenue, rooms_sold):
    return room_revenue / rooms_sold


def revenue_per_available_room(room_revenue, rooms_available):
    return room_revenue / rooms_available


def total_revenue(room_revenue, food_revenue, other_revenue):
    return room_revenue + food_revenue + other_revenue


def operating_expenses(fixed_costs, variable_cost_per_room, rooms_sold):
    return fixed_costs + variable_cost_per_room * rooms_sold


def gross_operating_profit(revenue, expenses):
    return revenue - expenses


def profit_margin(profit, revenue):
    return profit / revenue


def break_even_occupancy(fixed_costs, adr, variable_cost_per_room):
    return fixed_costs / (adr - variable_cost_per_room)


def validate(data):
    if len(data) != 7:
        raise ValueError("expected 7 base figures")
    rooms_sold, rooms_available = data[0], data[1]
    if rooms_available <= 0:
        raise ValueError("rooms available must be positive")
    if rooms_sold <= 0 or rooms_sold > rooms_available:
        raise ValueError("rooms sold must be between 1 and rooms available")
    return [float(value) for value in data]


def hospitality(data):
    (rooms_sold, rooms_available, room_revenue, food_revenue,
     other_revenue, fixed_costs, variable_cost_per_room) = validate(data)
    occupancy = occupancy_rate(rooms_sold, rooms_available)
    adr = average_daily_rate(room_revenue, rooms_sold)
    revpar = revenue_per_available_room(room_revenue, rooms_available)
    revenue = total_revenue(room_revenue, food_revenue, other_revenue)
    expenses = operating_expenses(fixed_costs, variable_cost_per_room, rooms_sold)
    profit = gross_operating_profit(revenue, expenses)
    margin = profit_margin(profit, revenue)
    break_even = break_even_occupancy(fixed_costs, adr, variable_cost_per_room)
    return (occupancy, adr, revpar, revenue, expenses, profit, margin, break_even)


def format_report(metrics):
    occupancy, adr, revpar, revenue, expenses, profit, margin, break_even = metrics
    lines = [
        "Occupancy rate:            {:.2%}".format(occupancy),
        "Average daily rate:        {:.2f}".format(adr),
        "RevPAR:                    {:.2f}".format(revpar),
        "Total revenue:             {:.2f}".format(revenue),
        "Operating expenses:        {:.2f}".format(expenses),
        "Gross operating profit:    {:.2f}".format(profit),
        "Profit margin:             {:.2%}".format(margin),
        "Break-even rooms sold:     {:.1f}".format(break_even),
    ]
    return "\n".join(lines)


def main():
    data = [850, 1000, 127500.0, 34000.0, 8500.0, 62000.0, 28.0]
    print(format_report(hospitality(data)))


if __name__ == "__main__":
    main()

