def validate(data):
    if len(data) != 2:
        raise ValueError("payroll data must contain hours worked and hourly rate")
    hours, rate = data
    if hours < 0 or rate < 0:
        raise ValueError("hours worked and hourly rate must be non-negative")
    return float(hours), float(rate)

def regular_pay(hours, rate):
    return round(min(hours, 40) * rate, 2)

def overtime_pay(hours, rate):
    return round(max(hours - 40, 0) * rate * 1.5, 2)

def gross_pay(regular, overtime):
    return round(regular + overtime, 2)

def federal_tax(gross):
    return round(gross * 0.12, 2)

def state_tax(gross):
    return round(gross * 0.05, 2)

def social_security(gross):
    return round(gross * 0.062, 2)

def medicare(gross):
    return round(gross * 0.0145, 2)

def net_pay(gross, deductions):
    return round(gross - sum(deductions), 2)

def payroll(data):
    hours, rate = validate(data)
    regular = regular_pay(hours, rate)
    overtime = overtime_pay(hours, rate)
    gross = gross_pay(regular, overtime)
    federal = federal_tax(gross)
    state = state_tax(gross)
    social = social_security(gross)
    care = medicare(gross)
    net = net_pay(gross, [federal, state, social, care])
    return [regular, overtime, gross, federal, state, social, care, net]

def format_paycheck(data, components):
    labels = ["Regular pay", "Overtime pay", "Gross pay", "Federal tax",
              "State tax", "Social security", "Medicare", "Net pay"]
    header = "Paycheck for {0:g} hours at {1:g}/hour".format(*validate(data))
    lines = [header, "-" * len(header)]
    for label, amount in zip(labels, components):
        lines.append("{0:<16}{1:>10.2f}".format(label, amount))
    return "\n".join(lines)

def main():
    timesheets = [[40, 10], [45, 20], [38, 15.5]]
    for sheet in timesheets:
        print(format_paycheck(sheet, payroll(sheet)))
        print()


if __name__ == "__main__":
    main()

