def reverse_string(s):
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string, got %r" % type(s).__name__)
    return s[::-1]


def reverse_words(text):
    return " ".join(reverse_string(word) for word in text.split(" "))


def is_palindrome(s, ignore_case=True):
    cleaned = "".join(ch for ch in s if ch.isalnum())
    if ignore_case:
        cleaned = cleaned.lower()
    return cleaned == reverse_string(cleaned)


def reverse_lines(text):
    return "\n".join(reverse_string(line) for line in text.splitlines())


def longest_reversible_run(s):
    best = ""
    current = ""
    for ch in s:
        if ch.isalnum():
            current += ch
        else:
            current = ""
        if len(current) > len(best):
            best = current
    return reverse_string(best)


def describe(s):
    parts = [
        "input:      %r" % s,
        "reversed:   %r" % reverse_string(s),
        "words:      %r" % reverse_words(s),
        "palindrome: %s" % is_palindrome(s),
    ]
    run = longest_reversible_run(s)
    if run:
        parts.append("run:        %r" % run)
    return "\n".join(parts)


def main():
    samples = [
        "hello",
        "Python",
        "A man, a plan, a canal: Panama",
        "never odd or even",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)
    block = "first line\nsecond line\nthird line"
    print(reverse_lines(block))


if __name__ == "__main__":
    main()

