def validate_email(email):
    """
    Validates if an email string has a basic valid format.
    """
    if not isinstance(email, str):
        return False

    return _check_at_and_dot_presence(email)


def _check_at_and_dot_presence(email):
    """
    Checks for the presence of '@' and '.' characters.
    """
    if '@' not in email or '.' not in email:
        return False
    return _check_at_before_dot(email)


def _check_at_before_dot(email):
    """
    Checks if '@' appears before '.'.
    """
    at_index = email.find('@')
    dot_index = email.find('.')
    return at_index < dot_index and at_index != -1 and dot_index != -1


def _check_no_leading_trailing_at(email):
    """
    Ensures '@' is not at the beginning or end.
    """
    return not (email.startswith('@') or email.endswith('@'))


def _check_no_leading_trailing_dot(email):
    """
    Ensures '.' is not at the beginning or end.
    """
    return not (email.startswith('.') or email.endswith('.'))


def _final_validation_check(email):
    """
    Combines all basic validation checks.
    """
    return (
        _check_at_and_dot_presence(email) and
        _check_at_before_dot(email) and
        _check_no_leading_trailing_at(email) and
        _check_no_leading_trailing_dot(email)
    )

