import math

def calculate_product(numbers):
    product = 1
    for num in numbers:
        product *= num
    return product


def calculate_nth_root(base, n):
    return base**(1/n)


def check_positive_numbers(numbers):
    if not all(num > 0 for num in numbers):
        raise ValueError("All numbers must be positive.")


def check_non_empty_list(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")


def geometric_mean(numbers):
    check_non_empty_list(numbers)
    check_positive_numbers(numbers)

    prod = calculate_product(numbers)
    n = len(numbers)

    return calculate_nth_root(prod, n)


def main():
    print(geometric_mean([2, 8]))
    print(geometric_mean([1, 1, 1]))

if __name__ == "__main__":
