def most_frequent_char(text):
    char_counts = get_char_counts(text)
    return find_most_frequent(char_counts, text)


def get_char_counts(text):
    counts = {}
    for char in text:
        normalized_char = normalize_char(char)
        if normalized_char:
            counts[normalized_char] = counts.get(normalized_char, 0) + 1
    return counts


def normalize_char(char):
    if char.isspace():
        return None
    return char.lower()


def find_most_frequent(char_counts, original_text):
    max_count = -1
    most_frequent = None
    for char in original_text:
        normalized_char = normalize_char(char)
        if normalized_char and char_counts[normalized_char] > max_count:
            max_count = char_counts[normalized_char]
            most_frequent = normalized_char
    return most_frequent


def get_char_order(text):
    order = {}
    for i, char in enumerate(text):
        normalized_char = normalize_char(char)
        if normalized_char and normalized_char not in order:
            order[normalized_char] = i
    return order


def resolve_ties(char_counts, char_order):
    max_count = 0
    for count in char_counts.values():
        max_count = max(max_count, count)

    tied_chars = []
    for char, count in char_counts.items():
        if count == max_count:
            tied_chars.append(char)

    if not tied_chars:
        return None

    if len(tied_chars) == 1:
        return tied_chars[0]

    min_index = float('inf')
    first_char = None
    for char in tied_chars:
        if char_order[char] < min_index:
            min_index = char_order[char]
            first_char = char
    return first_char

