def group_runs(s):
    runs = []
    for ch in s:
        if runs and runs[-1][0] == ch:
            runs[-1] = (ch, runs[-1][1] + 1)
        else:
            runs.append((ch, 1))
    return runs


def run_length_encode(s):
    if not isinstance(s, str):
        raise TypeError("run_length_encode expects a string")
    return "".join("%s%d" % (ch, count) for ch, count in group_runs(s))


def parse_encoded(s):
    runs = []
    index = 0
    while index < len(s):
        ch = s[index]
        index += 1
        digits = ""
        while index < len(s) and s[index].isdigit():
            digits += s[index]
            index += 1
        if not digits:
            raise ValueError("missing count for %r at position %d" % (ch, index - 1))
        runs.append((ch, int(digits)))
    return runs


def run_length_decode(s):
    return "".join(ch * count for ch, count in parse_encoded(s))


def compression_ratio(original, encoded):
    if not original:
        return 1.0
    return len(encoded) / len(original)


def describe_runs(s):
    lines = []
    for ch, count in group_runs(s):
        label = "time" if count == 1 else "times"
        lines.append("  %r repeated %d %s" % (ch, count, label))
    return "\n".join(lines)


def report(s):
    encoded = run_length_encode(s)
    ratio = compression_ratio(s, encoded)
    lines = ["%r -> %r (ratio %.2f)" % (s, encoded, ratio)]
    detail = describe_runs(s)
    if detail:
        lines.append(detail)
    lines.append("  decodes back to %r" % run_length_decode(encoded))
    return "\n".join(lines)


def main():
    samples = [
        "AAABBC",
        "A",
        "",
        "WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWW",
        "aabbaa",
    ]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

