def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    return _check_balance(s, stack, mapping)


def _check_balance(s: str, stack: list, mapping: dict) -> bool:
    for char in s:
        if _is_opening_bracket(char, mapping):
            stack.append(char)
        elif _is_closing_bracket(char, mapping):
            if not stack or stack.pop() != mapping[char]:
                return False
    return _is_stack_empty(stack)


def _is_opening_bracket(char: str, mapping: dict) -> bool:
    return char in mapping.values()


def _is_closing_bracket(char: str, mapping: dict) -> bool:
    return char in mapping.keys()


def _is_stack_empty(stack: list) -> bool:
    return not stack


