def _copy_dict(d: dict) -> dict:
    return d.copy()

def _add_new_keys(target: dict, source: dict):
    for key, value in source.items():
        if key not in target:
            target[key] = value

def _update_existing_keys(target: dict, source: dict):
    for key, value in source.items():
        if key in target:
            target[key] = value

def _merge_dictionaries_internal(dict1: dict, dict2: dict) -> dict:
    result = _copy_dict(dict1)
    _update_existing_keys(result, dict2)
    _add_new_keys(result, dict2)
    return result

def update_dict(dict1: dict, dict2: dict) -> dict:
    return _merge_dictionaries_internal(dict1, dict2)

def _test_update_dict():
    assert update_dict({'a': 1, 'b': 2}, {'b': 3, 'c': 4}) == {'a': 1, 'b': 3, 'c': 4}
    assert update_dict({'x': 10}, {'y': 20}) == {'x': 10, 'y': 20}
    assert update_dict({}, {'a': 1}) == {'a': 1}
    assert update_dict({'a': 1}, {}) == {'a': 1}
    assert update_dict({}, {}) == {}


_test_update_dict()

