def calculate_numerator(values, weights):
    return sum(v * w for v, w in zip(values, weights))


def calculate_denominator(weights):
    return sum(weights)


def handle_zero_denominator(denominator):
    if denominator == 0:
        raise ValueError("Sum of weights cannot be zero.")
    return denominator


def perform_division(numerator, denominator):
    return numerator / denominator


