def count_characters(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts


def find_minimum_count(counts):
    if not counts:
        return float('inf')
    return min(counts.values())


def find_least_frequent_character(text, counts, min_count):
    for char in text:
        if counts[char] == min_count:
            return char
    return ''


def is_empty_string(text):
    return not text


def handle_empty_string():
    return ''


def least_frequent_char(text):
    if is_empty_string(text):
        return handle_empty_string()

    char_counts = count_characters(text)
    min_occurrence = find_minimum_count(char_counts)
    return find_least_frequent_character(text, char_counts, min_occurrence)

