def join_words_to_sentence(words):
    return ' '.join(words)

def reverse_each_word(sentence):
    words = split_sentence_into_words(sentence)
    reversed_words = process_words(words)
    result_sentence = join_words_to_sentence(reversed_words)
    return result_sentence

def example_usage():
    print(reverse_each_word('hello world'))
    print(reverse_each_word('Python is fun'))

