def validate_text(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    return text


def validate_char(char_to_count):
    if not isinstance(char_to_count, str):
        raise TypeError("char_to_count must be a str")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    return char_to_count


def count_char(text, char_to_count):
    text = validate_text(text)
    char_to_count = validate_char(char_to_count)
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def count_char_ignore_case(text, char_to_count):
    return count_char(text.lower(), validate_char(char_to_count).lower())


def char_frequencies(text):
    frequencies = {}
    for character in validate_text(text):
        frequencies[character] = frequencies.get(character, 0) + 1
    return frequencies


def most_common_char(text):
    frequencies = char_frequencies(text)
    if not frequencies:
        return None
    return max(sorted(frequencies), key=frequencies.get)


def format_report(text, char_to_count):
    exact = count_char(text, char_to_count)
    relaxed = count_char_ignore_case(text, char_to_count)
    lines = [
        "text            : %r" % text,
        "character       : %r" % char_to_count,
        "exact matches   : %d" % exact,
        "case-insensitive: %d" % relaxed,
    ]
    top = most_common_char(text)
    if top is not None:
        lines.append("most common     : %r (%d)" % (top, count_char(text, top)))
    return "\n".join(lines)


def main():
    samples = [
        ("banana", "a"),
        ("Mississippi", "s"),
        ("Hello World", "o"),
        ("", "x"),
    ]
