def sum_digits(n):
    return sum(int(digit) for digit in str(n))


def double_and_sum(digit):
    doubled = int(digit) * 2
    return sum_digits(doubled)


def process_even_indexed(card_number):
    total = 0
    for i in range(len(card_number) - 2, -1, -2):
        total += double_and_sum(card_number[i])
    return total


def process_odd_indexed(card_number):
    total = 0
    for i in range(len(card_number) - 1, -1, -2):
        total += int(card_number[i])
    return total


def calculate_luhn_sum(card_number):
    even_sum = process_even_indexed(card_number)
    odd_sum = process_odd_indexed(card_number)
    return even_sum + odd_sum


def is_valid_luhn(card_number):
    luhn_sum = calculate_luhn_sum(card_number)
    return luhn_sum % 10 == 0

