class Queue:
    def __init__(self):
        self._items = []


    def enqueue(self, item):
        self._items.append(item)


    def dequeue(self):
        if not self._items:
            return None
        return self._items.pop(0)


def create_queue():
    return Queue()


def add_to_queue(q, item):
    q.enqueue(item)


def remove_from_queue(q):
    return q.dequeue()


def test_enqueue_dequeue():
    q = create_queue()
    add_to_queue(q, 1)
    result = remove_from_queue(q)
    assert result == 1, f"Expected 1, got {result}"


def test_empty_dequeue():
    q = create_queue()
    result = remove_from_queue(q)
    assert result is None, f"Expected None, got {result}"


def test_multiple_items():
    q = create_queue()
    add_to_queue(q, 10)
    add_to_queue(q, 20)
    assert remove_from_queue(q) == 10
    assert remove_from_queue(q) == 20
    assert remove_from_queue(q) is None

