import math


def calculate_delta_x(x1, x2):
    return x2 - x1


def calculate_delta_y(y1, y2):
    return y2 - y1


def square_value(value):
    return value ** 2


def sum_of_squares(val1_squared, val2_squared):
    return val1_squared + val2_squared


def take_square_root(value):
    return math.sqrt(value)


def euclidean_distance_2d(x1, y1, x2, y2):
    dx = calculate_delta_x(x1, x2)
    dy = calculate_delta_y(y1, y2)
    dx_squared = square_value(dx)
    dy_squared = square_value(dy)
    sum_sq = sum_of_squares(dx_squared, dy_squared)
    distance = take_square_root(sum_sq)
    return distance

