class BankAccount:
    def __init__(self, initial_balance):
        self._balance = initial_balance

    def _get_balance(self):
        return self._balance

    def deposit(self, amount):
        return self._perform_deposit(amount)

    def withdraw(self, amount):
        return self._perform_withdraw(amount)

    def _perform_deposit(self, amount):
        if self._is_valid_amount(amount):
            self._balance += amount
            return True
        return False

    def _perform_withdraw(self, amount):
        if self._is_valid_amount(amount) and self._has_sufficient_funds(amount):
            self._balance -= amount
            return True
        return False

    def _has_sufficient_funds(self, amount):
        return self._balance >= amount

    def _is_valid_amount(self, amount):
        return isinstance(amount, (int, float)) and amount > 0

