def _all_numbers_valid(numbers):
    return all(_is_valid_number(num) for num in numbers)


def _calculate_product(numbers):
    product = 1.0
    for num in numbers:
        product *= num
    return product


def _calculate_nth_root(product, n):
    return product**(1/n)


