def _initialize_dp_table(rows, cols):
    return [[0] * cols for _ in range(rows)]


def _fill_first_row_and_column(dp_table, s1_len, s2_len):
    for i in range(s1_len + 1):
        dp_table[i][0] = i
    for j in range(s2_len + 1):
        dp_table[0][j] = j


def _calculate_cost(char1, char2):
    return 0 if char1 == char2 else 1


def _fill_remaining_cells(dp_table, s1, s2):
    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            cost = _calculate_cost(s1[i-1], s2[j-1])
            dp_table[i][j] = min(
                dp_table[i-1][j] + 1,      # Deletion
                dp_table[i][j-1] + 1,      # Insertion
                dp_table[i-1][j-1] + cost  # Substitution or Match
            )


def levenshtein_distance(s1, s2):
    rows = len(s1) + 1
    cols = len(s2) + 1
    dp_table = _initialize_dp_table(rows, cols)
    _fill_first_row_and_column(dp_table, len(s1), len(s2))
    _fill_remaining_cells(dp_table, s1, s2)
    return _get_final_distance(dp_table)


def _get_final_distance(dp_table):
    return dp_table[-1][-1]

