def get_digit_char(value):
    if 0 <= value <= 9:
        return str(value)
    elif 10 <= value <= 15:
        return chr(ord('A') + value - 10)
    else:
        raise ValueError("Digit value out of range")


def convert_single_digit(remainder):
    return get_digit_char(remainder)


def calculate_remainder_and_quotient(number, base):
    return number % base, number // base


def build_result_string(digits):
    return "".join(digits)


def reverse_string(s):
    return s[::-1]


def convert_base(number, base):
    if not (2 <= base <= 16):
        raise ValueError("Base must be between 2 and 16")
    if number == 0:
        return "0"

    digits = []
    current_number = number
    while current_number > 0:
        remainder, current_number = calculate_remainder_and_quotient(current_number, base)
        digit_char = convert_single_digit(remainder)
        digits.append(digit_char)

    return reverse_string(build_result_string(digits))

