import re

def _split_into_words_and_punctuation(sentence):
    return re.findall(r"[\w']+|[.,!?;:]", sentence)


def _is_punctuation(token):
    return re.match(r"^[.,!?;:]$", token)


def _join_word_and_punctuation(word, punctuation):
    return word + punctuation


def reverse_words_with_punctuation(sentence):
    tokens = _split_into_words_and_punctuation(sentence)
    reversed_words = _reverse_words(tokens)
    return _reconstruct_sentence(reversed_words)


def _reverse_words(tokens):
    words = []
    punctuation_stack = []
    for token in reversed(tokens):
        if _is_punctuation(token):
            punctuation_stack.append(token)
        else:
            word_with_punct = token
            while punctuation_stack:
                word_with_punct += punctuation_stack.pop()
            words.append(word_with_punct)
    return words


def _reconstruct_sentence(reversed_words):
    return ' '.join(reversed_words)

