SIMULATED_FILES = {
    'dummy_file.txt': 'apple banana a',
    'empty.txt': '',
    'notes.txt': 'The quick brown fox jumps over 1234567 lazy dogs.',
    'code.txt': 'x1 = compute_total(items); y = x1 ** 2  # version2 build42',
}


def read_simulated_file(filepath):
    if filepath not in SIMULATED_FILES:
        raise FileNotFoundError(filepath)
    return SIMULATED_FILES[filepath]


def extract_words(text):
    words = []
    current = []
    for char in text:
        if char.isalnum():
            current.append(char)
        elif current:
            words.append(''.join(current))
            current = []
    if current:
        words.append(''.join(current))
    return words


def longest_word(words):
    best = ''
    for word in words:
        if len(word) > len(best):
            best = word
    return best


def find_longest_word_in_file(filepath):
    try:
        text = read_simulated_file(filepath)
    except FileNotFoundError:
        return ''
    return longest_word(extract_words(text))


def word_length_histogram(words):
    histogram = {}
    for word in words:
        histogram[len(word)] = histogram.get(len(word), 0) + 1
    return histogram


def describe_file(filepath):
    try:
        text = read_simulated_file(filepath)
    except FileNotFoundError:
        return '{0}: not found'.format(filepath)
    words = extract_words(text)
    if not words:
        return '{0}: empty (no words)'.format(filepath)
    histogram = word_length_histogram(words)
    spread = ', '.join(
        '{0}->{1}'.format(size, histogram[size]) for size in sorted(histogram)
    )
    return '{0}: {1} words, longest={2!r}, lengths [{3}]'.format(
        filepath, len(words), longest_word(words), spread
    )


def main():
    for name in ['dummy_file.txt', 'empty.txt', 'notes.txt', 'code.txt', 'gone.txt']:
        print(describe_file(name))
    print('answer for dummy_file.txt:', repr(find_longest_word_in_file('dummy_file.txt')))
    print('answer for empty.txt:', repr(find_longest_word_in_file('empty.txt')))


if __name__ == '__main__':
    main()

