def parse_numbers(text):
    """Convert a whitespace/comma separated string into a list of numbers."""
    tokens = [token for token in text.replace(",", " ").split() if token]
    numbers = []
    for token in tokens:
        value = float(token)
        numbers.append(int(value) if value.is_integer() else value)
    return numbers

def validate_data(data):
    """Ensure every element is a real number, returning the values as a list."""
    values = list(data)
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("calculate_mode expects numbers, got %r" % (value,))
    return values

def count_frequencies(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts

def calculate_mode(data):
    values = validate_data(data)
    if not values:
        return []
    counts = count_frequencies(values)
    highest = max(counts.values())
    return [value for value in counts if counts[value] == highest]

def sorted_modes(data):
    """The modes in ascending order, which makes reporting deterministic."""
    return sorted(calculate_mode(data))

def describe_modes(data):
    modes = sorted_modes(data)
    if not modes:
        return "no data, so no mode"
    counts = count_frequencies(validate_data(data))
    times = counts[modes[0]]
    listed = ", ".join(str(mode) for mode in modes)
    label = "mode" if len(modes) == 1 else "modes"
    return "%s: %s (appearing %d time%s)" % (label, listed, times, "" if times == 1 else "s")

def report(datasets):
    lines = []
    for dataset in datasets:
        lines.append("%s -> %s" % (dataset, describe_modes(dataset)))
    return "\n".join(lines)

def main():
    datasets = [
        [1, 2, 2, 3, 3, 3, 4],
        [1, 1, 2, 2, 3],
        [],
        parse_numbers("4.5, 4.5, 7, 7, 9"),
        parse_numbers("10 20 30"),
    ]
    print(report(datasets))


if __name__ == "__main__":
    main()

