def get_first_char(s: str) -> str:
    return s[0] if s else ''


def get_rest_of_string(s: str) -> str:
    return s[1:] if len(s) > 1 else ''


def is_empty(s: str) -> bool:
    return len(s) == 0


def reverse_string_recursive(s: str) -> str:
    if is_empty(s):
        return ""

    first = get_first_char(s)
    rest = get_rest_of_string(s)

    return concatenate_reversed(reverse_string_recursive(rest), first)


def concatenate_reversed(reversed_rest: str, char: str) -> str:
    return reversed_rest + char


def test_reverse_string():
    assert reverse_string_recursive('hello') == 'olleh'
    assert reverse_string_recursive('python') == 'nohtyp'
    assert reverse_string_recursive('') == ''
    assert reverse_string_recursive('a') == 'a'

test_reverse_string()

