def is_negative(n):
    return n < 0


def get_absolute_value(n):
    return abs(n)


def convert_to_string(n):
    return str(n)


def reverse_string(s):
    return s[::-1]


def convert_to_int(s):
    return int(s)


def reverse_integer(num):
    sign = -1 if is_negative(num) else 1
    abs_num = get_absolute_value(num)
    str_num = convert_to_string(abs_num)
    reversed_str = reverse_string(str_num)
    reversed_int = convert_to_int(reversed_str)
    return sign * reversed_int

