def justify_text_simple(words, max_width):
    lines = []
    current_line_words = []
    current_line_length = 0

    for word in words:
        if not current_line_words:
            current_line_words.append(word)
            current_line_length = len(word)
        elif current_line_length + 1 + len(word) <= max_width:
            current_line_words.append(word)
            current_line_length += 1 + len(word)
        else:
            lines.append(format_line(current_line_words, max_width))
            current_line_words = [word]
            current_line_length = len(word)

    if current_line_words:
        lines.append(format_last_line(current_line_words))

    return "\n".join(lines)


def format_line(words, max_width):
    if len(words) == 1:
        return words[0] + " " * (max_width - len(words[0]))

    total_word_length = sum(len(w) for w in words)
    total_spaces_needed = max_width - total_word_length
    num_gaps = len(words) - 1

    base_spaces = total_spaces_needed // num_gaps
    extra_spaces = total_spaces_needed % num_gaps

    result = []
    for i, word in enumerate(words):
        result.append(word)
        if i < num_gaps:
            spaces_to_add = base_spaces + (1 if i < extra_spaces else 0)
            result.append(" " * spaces_to_add)

    return "".join(result)


def format_last_line(words):
    return " ".join(words)


def _get_line_length(words):
    if not words:
        return 0
    return sum(len(word) for word in words) + len(words) - 1


def _can_add_word(current_line_length, word_length, max_width):
    if current_line_length == 0:
        return word_length <= max_width
    return current_line_length + 1 + word_length <= max_width


def _combine_lines(lines):
    return "\n".join(lines)

