def calculate_sample_std_dev(numbers):
    if len(numbers) < 2:
        return 0.0

    mean_val = calculate_mean(numbers)
    sum_squared_diff = calculate_sum_squared_differences(numbers, mean_val)
    variance = calculate_variance(sum_squared_diff, len(numbers))
    std_dev = calculate_square_root(variance)
    return std_dev


def calculate_mean(numbers):
    return sum(numbers) / len(numbers)


def calculate_sum_squared_differences(numbers, mean_val):
    return sum((x - mean_val) ** 2 for x in numbers)


def calculate_variance(sum_squared_diff, count):
    return sum_squared_diff / (count - 1)


def calculate_square_root(value):
    return value ** 0.5


def check_example_1():
    result = calculate_sample_std_dev([1, 2, 3])
    print(f"Example 1: [1, 2, 3] -> {result}")

def check_example_2():
    result = calculate_sample_std_dev([10, 20, 30, 40])
    print(f"Example 2: [10, 20, 30, 40] -> {result}")

check_example_1()
check_example_2()

