from urllib.parse import urlparse


def _get_hostname(url):
    parsed_url = urlparse(url)
    return parsed_url.hostname


def _remove_www_prefix(hostname):
    if hostname.startswith('www.'):
        return hostname[4:]
    return hostname


def _split_domain_parts(hostname_without_www):
    return hostname_without_www.split('.')


def _get_main_domain(domain_parts):
    return domain_parts[0]


def extract_domain(url):
    hostname = _get_hostname(url)
    hostname_without_www = _remove_www_prefix(hostname)
    domain_parts = _split_domain_parts(hostname_without_www)
    return _get_main_domain(domain_parts)


def _test_extract_domain():
    assert extract_domain('http://www.google.com/search') == 'google'
    assert extract_domain('https://blog.openai.org/post') == 'openai'
    assert extract_domain('http://example.co.uk') == 'example'


_test_extract_domain()

