from datetime import date, timedelta

def get_next_business_day(start_date: date) -> date:
    next_day = increment_date_by_one(start_date)
    return adjust_for_weekend(next_day)


def increment_date_by_one(current_date: date) -> date:
    return current_date + timedelta(days=1)


def is_weekend(check_date: date) -> bool:
    return check_date.weekday() in [5, 6]  # Saturday is 5, Sunday is 6


def adjust_for_weekend(candidate_date: date) -> date:
    while is_weekend(candidate_date):
        candidate_date = increment_date_by_one(candidate_date)
    return candidate_date


def run_example_one():
    d1 = date(2023, 10, 26)
    expected1 = date(2023, 10, 27)
    result1 = get_next_business_day(d1)
    assert result1 == expected1, f"Example 1 failed: Expected {expected1}, got {result1}"


def run_example_two():
    d2 = date(2023, 10, 27)
    expected2 = date(2023, 10, 30)
    result2 = get_next_business_day(d2)
    assert result2 == expected2, f"Example 2 failed: Expected {expected2}, got {result2}"

run_example_one()
run_example_two()

