import math

def calculate_distance(p1, p2):
    return abs(p1 - p2)


def sort_points(points):
    return sorted(points)


def initialize_min_distance_data():
    return math.inf, None, None


def update_min_distance_data(current_min_dist, current_p1, current_p2, new_dist, new_p1, new_p2):
    if new_dist < current_min_dist:
        return new_dist, new_p1, new_p2
    return current_min_dist, current_p1, current_p2


def find_closest_pair_1d(points):
    if len(points) < 2:
        raise ValueError("At least two points are required.")

    sorted_points = sort_points(points)
    min_dist, p1_closest, p2_closest = initialize_min_distance_data()

    for i in range(len(sorted_points) - 1):
        p1 = sorted_points[i]
        p2 = sorted_points[i+1]
        dist = calculate_distance(p1, p2)
        min_dist, p1_closest, p2_closest = update_min_distance_data(min_dist, p1_closest, p2_closest, dist, p1, p2)

    return (p1_closest, p2_closest)

