def _is_on_axis(x, y):
    return x == 0 or y == 0


def _determine_positive_x(x):
    return x > 0


def _determine_positive_y(y):
    return y > 0


def _get_quadrant_from_signs(positive_x, positive_y):
    if positive_x and positive_y:
        return 1
    elif not positive_x and positive_y:
        return 2
    elif not positive_x and not positive_y:
        return 3
    else: # positive_x and not positive_y
        return 4


def get_quadrant(x, y):
    if _is_on_axis(x, y):
        return 0
    else:
        positive_x = _determine_positive_x(x)
        positive_y = _determine_positive_y(y)
        return _get_quadrant_from_signs(positive_x, positive_y)


def _main():
    # Example usage (not part of the solution but for testing)
    print(get_quadrant(3, 5))
    print(get_quadrant(-2, 0))
    print(get_quadrant(-1, -1))
    print(get_quadrant(4, -2))
    print(get_quadrant(0, 7))

