import datetime

def is_business_day(day):
    return day.weekday() < 5

def count_business_days_in_month(year, month):
    return sum(1 for day in iterate_days_in_month(year, month) if is_business_day(day))

def get_days_in_month(year, month):
    if month == 12:
        return (datetime.date(year, month, 1), datetime.date(year + 1, 1, 1))
    return (datetime.date(year, month, 1), datetime.date(year, month + 1, 1))

def iterate_days_in_month(year, month):
    start_date, end_date = get_days_in_month(year, month)
    current_date = start_date
    while current_date < end_date:
        yield current_date
        current_date += datetime.timedelta(days=1)

def count_business_days(year, month):
    return count_business_days_in_month(year, month)

def main():
    print(count_business_days(2023, 10))
    print(count_business_days(2023, 11))

