def normalize_flips(flips):
    """Validate the input and return it in upper case."""
    if not isinstance(flips, str):
        raise TypeError("coin flips must be given as a string")
    cleaned = flips.strip().upper()
    invalid = sorted(set(cleaned) - {"H", "T"})
    if invalid:
        raise ValueError("unexpected flip symbols: " + ", ".join(invalid))
    return cleaned


def iter_streaks(flips):
    """Yield (symbol, length) pairs for each run of identical flips."""
    current = ""
    length = 0
    for flip in flips:
        if flip == current:
            length += 1
        else:
            if length:
                yield current, length
            current = flip
            length = 1
    if length:
        yield current, length


def longest_coin_flip_streak(flips):
    """Return the length of the longest run of consecutive heads or tails."""
    runs = iter_streaks(normalize_flips(flips))
    return max((length for _, length in runs), default=0)


def streak_summary(flips):
    """Return the longest streak length per side, keyed by symbol."""
    summary = {"H": 0, "T": 0}
    for symbol, length in iter_streaks(normalize_flips(flips)):
        if length > summary[symbol]:
            summary[symbol] = length
    return summary


def simulate_flips(count, seed=None):
    """Produce a pseudo-random flip string of the requested length."""
    import random

    if count < 0:
        raise ValueError("cannot simulate a negative number of flips")
    rng = random.Random(seed)
    return "".join(rng.choice("HT") for _ in range(count))


def format_report(flips):
    """Build a one-line human readable report for a flip sequence."""
    summary = streak_summary(flips)
    overall = longest_coin_flip_streak(flips)
    shown = flips if flips else "(no flips)"
    return "{0}: longest={1} heads={2} tails={3}".format(
        shown, overall, summary["H"], summary["T"]
    )


def main():
    sequences = ["HHHTTTHHHH", "HTHTHT", "", simulate_flips(20, seed=7)]
    for sequence in sequences:
        print(format_report(sequence))


if __name__ == "__main__":
    main()

